window.APP_DATA={"modules": [{"id": "funnel", "title": "Воронка", "icon": "↘", "stages": [{"title": "Acquisition / Visit", "summary": "Смотреть: users/sessions, source mix, GEO, device, new vs returning. · Главный вопрос: пришла ли релевантная аудитория и не изменился ли состав трафика?", "schema": "Смотреть: users/sessions, source mix, GEO, device, new vs returning. · Главный вопрос: пришла ли релевантная аудитория и не изменился ли состав трафика?", "terms": ["Users / Sessions", "Source mix", "GEO", "Device", "New vs Returning", "Attribution", "UTM", "Downstream conversion"], "problems": ["Резко изменился source mix.", "Один канал приводит аудиторию с другим поведением.", "GEO или устройство дают аномально слабую downstream-конверсию.", "Ошибка атрибуции или дублирование пользователей."], "diagnostics": ["Сравнить source/GEO/device до и после изменения.", "Смотреть не только вход, но и последующие шаги по каждой когорте.", "Проверить tracking/UTM/атрибуцию.", "Сравнить new vs returning."], "optimization": ["Согласовать обещание источника с первым экраном продукта.", "Исправить технические проблемы конкретной платформы/GEO.", "Разделить аналитику по качественно разным источникам вместо одной средней.", "Устранить ошибочную атрибуцию до продуктовых выводов."], "after": ["Смотреть downstream conversion, а не только объём визитов.", "Проверить cohort quality.", "Убедиться, что улучшение не вызвано просто изменением mix."]}, {"title": "Landing", "summary": "Смотреть: landing → next-step conversion, exits, load/error rate. · Главный вопрос: понимает ли пользователь, куда он попал и что делать дальше?", "schema": "Смотреть: landing → next-step conversion, exits, load/error rate. · Главный вопрос: понимает ли пользователь, куда он попал и что делать дальше?", "terms": ["Landing page", "Next-step conversion", "Exit rate", "Load time", "CTA", "Responsive", "Breakdown", "Uplift", "Guardrail"], "problems": ["Медленная загрузка или ошибки.", "Message mismatch между источником и landing.", "CTA плохо заметен или непонятен.", "Проблема только на mobile / конкретной версии.", "Неподходящая локализация."], "diagnostics": ["Breakdown по device/browser/version/GEO/source.", "Сравнить load time и conversion.", "Посмотреть paths/flows после landing.", "Проверить session/error logs."], "optimization": ["Упростить первый экран и hierarchy.", "Сделать следующий шаг однозначным.", "Исправить performance и responsive issues.", "Локализовать контент под реально проблемный сегмент."], "after": ["Primary: landing → next step conversion.", "Guardrails: errors, load time, exits.", "Проверить сегменты, а не только общий uplift."]}, {"title": "Sign-up", "summary": "Смотреть: start → complete conversion, field errors, abandonment, time-to-complete. · Главный вопрос: на каком именно поле/шаге пользователь прекращает процесс?", "schema": "Смотреть: start → complete conversion, field errors, abandonment, time-to-complete. · Главный вопрос: на каком именно поле/шаге пользователь прекращает процесс?", "terms": ["Start→Complete CR", "Field error rate", "Validation", "Abandonment", "Time-to-complete"], "problems": ["Слишком длинная форма.", "Непонятные требования к полям.", "Ошибки validation.", "Плохая клавиатура/маски ввода на mobile.", "Duplicate account / backend error."], "diagnostics": ["События на start, field error, step complete, form complete.", "Field-level error rate.", "Time between steps.", "Breakdown по OS/browser/version."], "optimization": ["Убрать необязательные поля.", "Inline validation вместо ошибки после submit.", "Показать понятную причину ошибки и способ исправления.", "Автозаполнение там, где это допустимо."], "after": ["Start → complete CR.", "Error rate по изменённым полям.", "Median completion time.", "Проверить, не ухудшилось ли качество данных."]}, {"title": "FTD — первый успешный депозит", "summary": "Переход зарегистрированного пользователя к первому успешному депозиту.", "schema": "Registration complete → cashier/payment flow → successful FTD.", "terms": ["FTD", "R2D / Reg2Dep", "Time-to-FTD", "Payment provider", "Success / fail rate"], "problems": ["Общий Reg→Dep может скрывать конкретный проблемный подшаг платежного пути."], "diagnostics": ["Разложить cashier open → method selected → transaction started → successful outcome.", "Breakdown по GEO/device/provider/version и error codes.", "Сопоставить frontend и backend outcome."], "optimization": ["Оптимизировать только после локализации bottleneck."], "after": ["Проверить Reg→FTD, fail rate, processing time и downstream quality."]}, {"title": "Onboarding / Setup", "summary": "Смотреть: completion, fail/retry rate, processing time, support contacts. · Главный вопрос: проблема в UX, внешнем сервисе, бизнес-правиле или технической реализации?", "schema": "Смотреть: completion, fail/retry rate, processing time, support contacts. · Главный вопрос: проблема в UX, внешнем сервисе, бизнес-правиле или технической реализации?", "terms": ["Completion rate", "Fail rate", "Retry", "Processing time", "Support contacts", "SLA", "Frontend event", "Backend outcome", "Recovery flow"], "problems": ["Долгое ожидание внешнего ответа.", "Непонятный статус процесса.", "Повторная попытка ведёт в тупик.", "Локальные требования отличаются по GEO.", "Технический failure masquerades as user drop-off."], "diagnostics": ["Разделить user cancel и system fail.", "Смотреть error_code / provider / GEO / retry.", "Сопоставить frontend event и backend outcome.", "Проверить SLA внешних зависимостей."], "optimization": ["Показать понятный статус и следующий шаг.", "Сделать безопасный retry/recovery flow.", "Сократить лишние переходы.", "Исправить GEO-specific правила и сообщения об ошибках."], "after": ["Completion rate.", "Fail/retry rate.", "Processing time.", "Support/error volume."]}, {"title": "Activation", "summary": "Смотреть: activation rate, time-to-value, долю пользователей, дошедших до first value. · Главный вопрос: получил ли новый пользователь ключевую ценность продукта достаточно быстро?", "schema": "Смотреть: activation rate, time-to-value, долю пользователей, дошедших до first value. · Главный вопрос: получил ли новый пользователь ключевую ценность продукта достаточно быстро?", "terms": ["Activation event", "Activation rate", "Time-to-value", "Downstream retention"], "problems": ["Регистрация завершена, но пользователь не понимает следующий шаг.", "Слишком много onboarding before value.", "Ключевая функция плохо обнаруживается.", "Activation event выбран неверно и не связан с последующим успехом."], "diagnostics": ["Paths от sign-up complete до activation.", "Сравнить activated vs non-activated cohorts.", "Проверить связь candidate activation events с downstream retention.", "Time-to-activation по сегментам."], "optimization": ["Сократить time-to-value.", "Явно показать следующий полезный шаг.", "Убрать необязательный onboarding перед первой ценностью.", "Пересмотреть activation definition на данных."], "after": ["Activation rate.", "Median time-to-value.", "Downstream retention активированных когорт.", "Guardrail: error/support rate."]}, {"title": "Core Action", "summary": "Смотреть: start → success, error rate, latency, abandonment, retries. · Главный вопрос: может ли пользователь стабильно завершить основной сценарий?", "schema": "Смотреть: start → success, error rate, latency, abandonment, retries. · Главный вопрос: может ли пользователь стабильно завершить основной сценарий?", "terms": ["Core action", "Success rate", "Error rate", "Latency", "Abandonment", "Retry event"], "problems": ["Технические ошибки.", "Высокая latency.", "Непонятный result/error state.", "Слишком много шагов.", "Один сегмент деградирует, среднее это скрывает."], "diagnostics": ["Success/error/retry events.", "Breakdown по version/device/GEO/user type.", "Paths до abandon.", "Сопоставить релизы и момент изменения."], "optimization": ["Устранить наиболее частые системные ошибки.", "Сократить ненужные шаги.", "Улучшить error recovery.", "Оптимизировать performance критичного сценария."], "after": ["Completion/success rate.", "Error rate.", "Latency.", "Поведение конкретных сегментов."]}, {"title": "Repeat Use", "summary": "Смотреть: repeat rate, time-to-second action, frequency, behavioral cohorts. · Главный вопрос: первая успешная сессия приводит к повторной продуктовой ценности или остаётся разовой?", "schema": "Смотреть: repeat rate, time-to-second action, frequency, behavioral cohorts. · Главный вопрос: первая успешная сессия приводит к повторной продуктовой ценности или остаётся разовой?", "terms": ["Repeat rate", "Time-to-second action", "Behavioral cohort", "Frequency"], "problems": ["Высокая первая конверсия, но мало повторного использования.", "Один source даёт много разовых пользователей.", "Пользователь не знает, зачем возвращаться к функции.", "После первого использования остаётся UX friction."], "diagnostics": ["Cohort by first action date.", "Time-to-second distribution.", "Source/GEO/device segmentation.", "Сравнить behavioral paths repeaters vs one-time users."], "optimization": ["Упростить повторный сценарий.", "Сделать состояние продукта понятным при возврате.", "Исправить friction, характерный именно для one-time cohort.", "Работать с причиной, найденной в сегменте, а не со всем продуктом сразу."], "after": ["Time-to-second.", "Repeat rate.", "Следующая retention-точка.", "Сравнить источник/сегмент, где была проблема."]}, {"title": "Retention", "summary": "Смотреть: cohort retention, rolling/N-day по смыслу продукта, churn signals, segment trend. · Главный вопрос: какая именно когорта перестала возвращаться и что изменилось в её опыте?", "schema": "Смотреть: cohort retention, rolling/N-day по смыслу продукта, churn signals, segment trend. · Главный вопрос: какая именно когорта перестала возвращаться и что изменилось в её опыте?", "terms": ["D1 / D7 / D30", "Exact-day retention", "Rolling retention", "Cohort retention", "Churn"], "problems": ["Общий D7 стабилен, но деградирует важная когорта.", "New и reactivated смешаны в одной метрике.", "Source mix искусственно меняет средний retention.", "После релиза изменилось поведение только одного сегмента."], "diagnostics": ["Retention по acquisition cohort.", "New / returning / reactivated отдельно.", "Source, GEO, device, version.", "Behavioral cohorts по ключевым ранним действиям.", "Проверить тренд, а не один D7 snapshot."], "optimization": ["Исправить конкретный friction сегмента с ухудшением.", "Улучшить обнаруживаемость полезных повторных сценариев.", "Исправить regressions после релиза.", "Убрать проблему ранней activation, если она коррелирует с churn."], "after": ["Сравнить новые когорты с baseline.", "Primary retention point + guardrails.", "Проверить, не улучшилось ли среднее за счёт смены состава аудитории."]}, {"title": "Реактивация / Win-back", "summary": "Возврат ранее активных пользователей после периода неактивности.", "schema": "Inactive → reactivated → repeat meaningful use.", "terms": ["Reactivation rate", "Inactive / dormant user", "Downstream retention"], "problems": ["Смешивание reactivated с new/returning и искажение общего retention."], "diagnostics": ["Отделять reactivated в отдельный сегмент/когорту.", "Сравнивать качество возврата и последующее удержание."], "optimization": ["Сначала понять причину ухода; коммуникация — только один из возможных инструментов."], "after": ["Reactivation rate + downstream retention + guardrails."]}], "source": "Merged A+B", "special": "funnel"}, {"id": "igaming_core", "title": "iGaming база", "icon": "⌁", "stages": [{"title": "Денежные метрики (unit-экономика)", "summary": "Связка для собеса. Вся воронка существует ради LTV > CAC с запасом ≥3–4× . Рост R2D и retention поднимает LTV; контроль bonus cost и качества трафика снижает эффективный CAC. Относительный рост конверсии на 20% даёт больше NGR, чем рост трафика на 20% — без до", "terms": ["GGR", "NGR", "Hold% / RTP", "Bonus ratio", "ARPU / ARPPU", "LTV", "Payback", "Связка для собеса", "LTV > CAC с запасом ≥3–4×"], "body": "<div class=\"kpi-strip\">\n<div class=\"kpi\"><div class=\"k\">LTV / CAC</div><div class=\"v\">≥ 3–4×</div><div class=\"d\">здоровая экономика</div></div>\n<div class=\"kpi\"><div class=\"k\">Bonus / GGR</div><div class=\"v\">&lt; 20%</div><div class=\"d\">промо под контролем</div></div>\n<div class=\"kpi\"><div class=\"k\">Max Acq. Cost</div><div class=\"v\">25–30%</div><div class=\"d\">от LTV сегмента</div></div>\n<div class=\"kpi\"><div class=\"k\">ARPU / мес</div><div class=\"v\">$100–200*</div><div class=\"d\">*Tier-1; emerging ниже</div></div>\n</div><div class=\"tbl-wrap\"><table>\n<tr><th style=\"width:15%;\">Метрика</th><th style=\"width:40%;\">Формула / определение</th><th style=\"width:22%;\">Ориентир</th><th style=\"width:23%;\">Смысл</th></tr>\n<tr><td><b>GGR</b></td><td class=\"mono\">оборот − выигрыши = оборот × hold%</td><td class=\"bnum\">рост ~10–15% г/г</td><td>валовая маржа до расходов</td></tr>\n<tr><td><b>NGR</b></td><td class=\"mono\">GGR − бонусы − налоги − комиссии (− chargeback)</td><td class=\"bnum\">рост ~5–10% г/г</td><td>база прибыли и RevShare</td></tr>\n<tr><td><b>Hold% / RTP</b></td><td class=\"mono\">GGR / оборот; казино = 100% − RTP</td><td class=\"bnum\">спорт 5–10%; RTP ~94–97%</td><td>сколько удерживается с оборота</td></tr>\n<tr><td><b>Bonus ratio</b></td><td class=\"mono\">стоимость бонусов / GGR</td><td class=\"bnum\">&lt; 20%</td><td>эффективность промо</td></tr>\n<tr><td><b>ARPU / ARPPU</b></td><td class=\"mono\">выручка / активные · выручка / платящие</td><td class=\"bnum\">$100–200/мес (Tier-1)</td><td>доход с активного / платящего</td></tr>\n<tr><td><b>LTV</b></td><td class=\"mono\">ARPU × срок жизни; лучше на марже, decay 15–25%/год</td><td class=\"bnum\">≥ 3–4× CAC</td><td>потолок затрат на привлечение</td></tr>\n<tr><td><b>Payback</b></td><td class=\"mono\">CAC / мес. маржа с игрока</td><td class=\"bnum\">короче — лучше</td><td>скорость окупаемости</td></tr>\n</table></div><div class=\"note green\" style=\"margin-top:12px;\">\n<b>Связка для собеса.</b> Вся воронка существует ради <b>LTV &gt; CAC с запасом ≥3–4×</b>. Рост R2D и retention поднимает LTV; контроль bonus cost и качества трафика снижает эффективный CAC. Относительный рост конверсии на 20% даёт больше NGR, чем рост трафика на 20% — без доп. затрат на привлечение.\n    </div>"}, {"title": "Риск & Anti-fraud", "summary": "Недооценённый пласт и сильный дифференциатор: фрод и злоупотребления едят NGR через фейковые FTD, bonus-abuse и chargeback.", "terms": ["Detection vs False-positive", "Risk-adaptive пороги", "Паттерны фейк-FTD", "Fraud ↔ выручка"], "body": "<p class=\"lead\">Недооценённый пласт и сильный дифференциатор: фрод и злоупотребления едят NGR через фейковые FTD, bonus-abuse и chargeback.</p><div class=\"grid2\">\n<div><div class=\"tbl-wrap\"><table>\n<tr><th>Метрика</th><th>Формула</th><th>Ориентир</th></tr>\n<tr><td>Chargeback rate</td><td class=\"mono\">чарджбэки / транзакции</td><td class=\"bnum\">&lt;1%, лучше &lt;0.5%</td></tr>\n<tr><td>Bonus abuse rate</td><td class=\"mono\">abuse-акк / получатели</td><td class=\"bnum\">минимизировать</td></tr>\n<tr><td>Multi-accounting</td><td class=\"mono\">связи device/IP/платёж</td><td class=\"bnum\">детект ↑</td></tr>\n<tr><td>KYC pass rate</td><td class=\"mono\">прошли / подали</td><td class=\"bnum\">&gt;80–90%</td></tr>\n</table></div></div>\n<div><div class=\"block-title\">Продуктовый баланс</div>\n<ul class=\"tips\">\n<li><b>Detection vs False-positive:</b> ключевой трейд-офф; жёсткие правила режут живых игроков.</li>\n<li><b>Risk-adaptive пороги:</b> строго на выводах/крупных бонусах, мягко на рутине.</li>\n<li><b>Паттерны фейк-FTD:</b> мин. депозиты с одного источника, общий fingerprint, аномальная скорость.</li>\n<li><b>Fraud ↔ выручка:</b> отклонённые FTD и chargeback напрямую уменьшают NGR.</li>\n</ul></div>\n</div>"}], "source": "Source A"}, {"id": "metrics", "title": "Продуктовые метрики", "icon": "▦", "stages": [{"title": "Требования к хорошей метрике", "summary": "Главный тест метрики: «Если значение изменится — что мы сделаем по-другому?» Нет ответа → метрика не нужна.", "terms": ["Число", "Понятна команде", "Привязана к цели", "Логичная формула", "Связана с другими", "Побуждает к действию", "Есть источник данных и период", "Главный тест метрики"], "body": "<div class=\"grid2\">\n<div><ul class=\"plain\">\n<li><b>Число</b> — иначе с ней нельзя системно работать.</li>\n<li><b>Понятна команде</b> — все одинаково трактуют.</li>\n<li><b>Привязана к цели</b> продукта, а не измеряет оторванное.</li>\n<li><b>Логичная формула</b> — прозрачная и воспроизводимая.</li>\n</ul></div>\n<div><ul class=\"plain\">\n<li><b>Связана с другими</b> — встроена в систему, не изолирована.</li>\n<li><b>Побуждает к действию</b> — иначе лишняя.</li>\n<li><b>Есть источник данных и период</b> измерения.</li>\n</ul></div>\n</div><div class=\"note green\"><b>Главный тест метрики:</b> «Если значение изменится — что мы сделаем по-другому?» Нет ответа → метрика не нужна.</div>"}, {"title": "Классификация: 9 категорий", "summary": "Категория Описание Примеры Acquisition Привлечение откуда приходят юзеры, эффективность каналов, стоимость привлечения кол-во юзеров, CAC, ROMI Activation Активация первый опыт, достижение aha-момента, привычка % дошедших до aha-момента Engagement Вовлечённост", "terms": ["Acquisition", "Activation", "Engagement", "Retention", "Revenue", "Happiness", "Technical", "Operational", "Specific"], "body": "<div class=\"tbl-wrap\"><table>\n<tr><th style=\"width:20%;\">Категория</th><th style=\"width:48%;\">Описание</th><th style=\"width:32%;\">Примеры</th></tr>\n<tr><td><b>Acquisition</b><br/>Привлечение</td><td>откуда приходят юзеры, эффективность каналов, стоимость привлечения</td><td>кол-во юзеров, CAC, ROMI</td></tr>\n<tr><td><b>Activation</b><br/>Активация</td><td>первый опыт, достижение aha-момента, привычка</td><td>% дошедших до aha-момента</td></tr>\n<tr><td><b>Engagement</b><br/>Вовлечённость</td><td>глубина, разнообразие, частота использования</td><td>время сессии, кол-во действий, набор функций</td></tr>\n<tr><td><b>Retention</b><br/>Удержание</td><td>возврат, регулярность, лояльность</td><td>DAU, MAU, возврат по циклу использования</td></tr>\n<tr><td><b>Revenue</b><br/>Доход</td><td>деньги от продукта, монетизация</td><td>LTV, прибыль, маржа</td></tr>\n<tr><td><b>Happiness</b><br/>Удовлетворённость</td><td>оценка и мнение пользователей</td><td>NPS, отзывы</td></tr>\n<tr><td><b>Technical</b><br/>Технические</td><td>работоспособность продукта без учёта юзеров</td><td>отказы, ошибки</td></tr>\n<tr><td><b>Operational</b><br/>Операционные</td><td>эффективность внутренних процессов и команд</td><td>затраты, продуктивность</td></tr>\n<tr><td><b>Specific</b><br/>Специфические</td><td>уникальные для конкретного продукта</td><td>спрос/предложение для маркетплейса</td></tr>\n</table></div>"}, {"title": "Aha-момент и North Star Metric", "summary": "Суть: супермаркет товаров. Действие: покупка. Монетизация: маржа. Входные метрики перемножаются:", "terms": ["долю дошедших", "time-to-aha", "отражает ценность, ведущую к росту дохода", "Ширина", "Интенсивность", "Частота", "Контрметрики (guardrails)"], "body": "<div class=\"grid2\">\n<div class=\"card\" style=\"flex:1 1 280px;\">\n<h3 class=\"card-title\">Aha-момент</h3>\n<p style=\"font-size:13.5px;\">Ключевое действие, после которого юзер осознаёт ценность продукта: первая покупка, добавление друзей. Измеряется через <b>долю дошедших</b> и <b>time-to-aha</b> (время до достижения).</p>\n</div>\n<div class=\"card\" style=\"flex:1 1 280px;\">\n<h3 class=\"card-title\">North Star Metric</h3>\n<p style=\"font-size:13.5px;\">Агрегированная ключевая метрика, отражающая успех через комплекс влияющих метрик. По подходу Amplitude — <b>отражает ценность, ведущую к росту дохода</b>.</p>\n</div>\n</div><div class=\"block-title\" style=\"margin-top:6px;\">NSM на примере интернет-магазина</div><p class=\"lead\">Суть: супермаркет товаров. Действие: покупка. Монетизация: маржа. Входные метрики перемножаются:</p><div class=\"formula\">\n      NSM = <b>Ширина</b> (MAU покупателей) × <b>Интенсивность</b> (средний чек) × <b>Частота</b> (покупок на клиента)\n    </div><div class=\"note\"><b>Контрметрики (guardrails).</b> Чтобы рост NSM не шёл за счёт качества, вводят ограничители: % возвратов, качество доставки, % не забранного товара.</div>"}, {"title": "Метрики по стадиям продукта", "summary": "Стадия Фокус метрик Задачи Problem-solution fit качественная обратная связь, кол-во юзеров подтвердить существование проблемы Product-market fit retention, engagement, acquisition, монетизация подтвердить готовность к масштабированию Growth acquisition, moneti", "terms": ["Problem-solution fit", "Product-market fit", "Growth", "Expansion / Maturity"], "body": "<div class=\"tbl-wrap\"><table>\n<tr><th style=\"width:22%;\">Стадия</th><th style=\"width:40%;\">Фокус метрик</th><th style=\"width:38%;\">Задачи</th></tr>\n<tr><td><b>Problem-solution fit</b></td><td>качественная обратная связь, кол-во юзеров</td><td>подтвердить существование проблемы</td></tr>\n<tr><td><b>Product-market fit</b></td><td>retention, engagement, acquisition, монетизация</td><td>подтвердить готовность к масштабированию</td></tr>\n<tr><td><b>Growth</b></td><td>acquisition, monetization, activation, retention, операционные</td><td>агрессивное масштабирование, поиск каналов</td></tr>\n<tr><td><b>Expansion / Maturity</b></td><td>операционная эффективность, технические, рост, монетизация</td><td>оптимизация, расширение рынков и юзкейсов</td></tr>\n</table></div>"}, {"title": "Внедрение метрик: рекомендации", "summary": "Сначала описать все метрики: формула, источник, владелец . Определить, каких метрик не хватает и нужны ли они сейчас , исходя из целей. Собрать здоровый дашборд — по 1–2 метрики из каждой категории. Использовать метрики для приоритизации и анализа влияния изме", "terms": ["формула, источник, владелец", "сейчас", "здоровый дашборд", "приоритизации", "дерево", "ответственный"], "body": "<ul class=\"tips\">\n<li>Сначала описать все метрики: <b>формула, источник, владелец</b>.</li>\n<li>Определить, каких метрик не хватает и нужны ли они <b>сейчас</b>, исходя из целей.</li>\n<li>Собрать <b>здоровый дашборд</b> — по 1–2 метрики из каждой категории.</li>\n<li>Использовать метрики для <b>приоритизации</b> и анализа влияния изменений.</li>\n<li>Метрики строят <b>дерево</b>: общая раскладывается на показатели влияния; у каждой — <b>ответственный</b> («без ответственного никто метрикой не управляет»).</li>\n</ul>"}, {"title": "Самопроверка по метрикам", "summary": "Вопросов: 6 Развернуть всё ", "terms": [], "body": "<div data-qa-group=\"\">\n</div>"}], "source": "Source A"}, {"id": "abtest", "title": "A/B testing", "icon": "A/B", "stages": [{"title": "Что тест делает и чего нет", "summary": "Делает Не делает Измеряет причинный эффект изменения Не гарантирует рост бизнеса Снижает риск ошибочных решений Не заменяет продуктовую стратегию Сравнивает варианты в равных условиях Не исправляет слабую гипотезу Валидирует гипотезу на данных Не отменяет каче", "terms": [], "body": "<div class=\"tbl-wrap\"><table>\n<tr><th style=\"width:50%;\">Делает</th><th style=\"width:50%;\">Не делает</th></tr>\n<tr><td>Измеряет причинный эффект изменения</td><td>Не гарантирует рост бизнеса</td></tr>\n<tr><td>Снижает риск ошибочных решений</td><td>Не заменяет продуктовую стратегию</td></tr>\n<tr><td>Сравнивает варианты в равных условиях</td><td>Не исправляет слабую гипотезу</td></tr>\n<tr><td>Валидирует гипотезу на данных</td><td>Не отменяет качественный анализ</td></tr>\n</table></div>"}, {"title": "Почему не «до-после»", "summary": "Сравнение «до/после» смешивает эффект фичи с внешним фоном:", "terms": [], "body": "<p class=\"lead\">Сравнение «до/после» смешивает эффект фичи с внешним фоном:</p><div class=\"tbl-wrap\"><table>\n<tr><th style=\"width:38%;\">Фактор</th><th>Как искажает</th></tr>\n<tr><td>Сезонность</td><td>метрика меняется сама по периоду</td></tr>\n<tr><td>Маркетинг</td><td>новый трафик другого качества</td></tr>\n<tr><td>Изменение цены/ставки</td><td>конверсия меняется независимо от фичи</td></tr>\n<tr><td>Гео/эконом. события</td><td>поведение сдвигается синхронно у всех</td></tr>\n</table></div>"}, {"title": "Базовая статистика для продакта", "summary": "Важно. Статистическая значимость ≠ бизнес-значимости. Эффект может быть «значимым», но слишком маленьким, чтобы оправдать внедрение.", "terms": ["MDE", "α (значимость)", "p-value", "Мощность (1-β)", "Доверит. интервал", "Важно"], "body": "<div class=\"tbl-wrap\"><table>\n<tr><th style=\"width:20%;\">Термин</th><th style=\"width:45%;\">Простыми словами</th><th style=\"width:35%;\">Почему важно</th></tr>\n<tr><td><b>MDE</b></td><td>минимальный эффект, который хотим детектить</td><td>меньше MDE → больше выборка</td></tr>\n<tr><td><b>α (значимость)</b></td><td>допустимая вероятность ложноположительного</td><td>обычно 5%; риск «увидеть» несуществующий эффект</td></tr>\n<tr><td><b>p-value</b></td><td>насколько необычен результат, если эффекта нет</td><td>значимость ≠ размер бизнес-эффекта</td></tr>\n<tr><td><b>Мощность (1-β)</b></td><td>шанс заметить реальный эффект</td><td>низкая → пропустим полезное</td></tr>\n<tr><td><b>Доверит. интервал</b></td><td>диапазон правдоподобных значений эффекта</td><td>показывает неопределённость, не только «есть/нет»</td></tr>\n</table></div><div class=\"note\"><b>Важно.</b> Статистическая значимость ≠ бизнес-значимости. Эффект может быть «значимым», но слишком маленьким, чтобы оправдать внедрение.</div>"}, {"title": "Проектирование эксперимента", "summary": "Хороший тест начинается не с разработки, а с дизайна. До запуска фиксируем:", "terms": ["Гипотеза", "Метрики", "Единица рандомизации", "Выборка и длительность", "Критерии успеха и условия остановки", "Трекинг", "Primary", "Secondary", "Guardrail", "Дисциплина"], "body": "<p class=\"lead\">Хороший тест начинается не с разработки, а с дизайна. До запуска фиксируем:</p><ul class=\"tips\">\n<li><b>Гипотеза:</b> какое изменение, для какой аудитории, за счёт какого механизма влияет на метрику.</li>\n<li><b>Метрики:</b> основная + второстепенные/защитные.</li>\n<li><b>Единица рандомизации:</b> юзер / аккаунт / устройство / сессия.</li>\n<li><b>Выборка и длительность</b> — из MDE, базовой конверсии и мощности.</li>\n<li><b>Критерии успеха и условия остановки</b> (только для тех. аномалий).</li>\n<li><b>Трекинг:</b> проверить события и корректность сплита; завершить по заранее заданному правилу.</li>\n</ul><div class=\"block-title\" style=\"margin-top:8px;\">Типы метрик эксперимента</div><div class=\"tbl-wrap\"><table>\n<tr><th style=\"width:26%;\">Тип</th><th style=\"width:40%;\">Назначение</th><th style=\"width:34%;\">Пример</th></tr>\n<tr><td><b>Primary</b></td><td>по ней принимают решение</td><td>конверсия в оплату, CTR CTA</td></tr>\n<tr><td><b>Secondary</b></td><td>объясняют механизм</td><td>переход к следующему шагу воронки</td></tr>\n<tr><td><b>Guardrail</b></td><td>не сломалось ли критичное</td><td>ошибки, скорость, возвраты, жалобы</td></tr>\n</table></div><div class=\"note\"><b>Дисциплина.</b> Primary-метрику нельзя выбирать после получения результатов — она фиксируется до запуска.</div>"}, {"title": "Типичные ошибки", "summary": "Ошибка Проблема Что делать Слабая гипотеза трафик и время в пустоту сначала проверить данные и механизм Нет дизайна непонятно, как решать зафиксировать всё до старта Подглядывание рост ложноположительных завершать по заданному правилу Сегменты постфактум «удоб", "terms": ["При SRM группы могут быть несопоставимы", "больше трафика"], "body": "<div class=\"tbl-wrap\"><table>\n<tr><th style=\"width:30%;\">Ошибка</th><th style=\"width:38%;\">Проблема</th><th style=\"width:32%;\">Что делать</th></tr>\n<tr><td>Слабая гипотеза</td><td>трафик и время в пустоту</td><td>сначала проверить данные и механизм</td></tr>\n<tr><td>Нет дизайна</td><td>непонятно, как решать</td><td>зафиксировать всё до старта</td></tr>\n<tr><td>Подглядывание</td><td>рост ложноположительных</td><td>завершать по заданному правилу</td></tr>\n<tr><td>Сегменты постфактум</td><td>«удобный» срез</td><td>сегменты задавать заранее / exploratory</td></tr>\n<tr><td>Неверная единица</td><td>сессии как юзеры</td><td>согласовать рандомизацию и критерий</td></tr>\n<tr><td>Игнор SRM</td><td>сбой 50/50 → несопоставимость</td><td>проверять SRM до интерпретации</td></tr>\n</table></div><div class=\"grid2\" style=\"margin-top:6px;\">\n<div class=\"card\" style=\"flex:1 1 280px;\">\n<h3 class=\"card-title\">SRM — красный флаг</h3>\n<p style=\"font-size:13.5px;\">Sample Ratio Mismatch: планировали 50/50, получили 60/40. Сам по себе не доказывает ошибку, но требует проверки реализации, фильтрации юзеров и логирования. <b>При SRM группы могут быть несопоставимы</b> — разница может оказаться техническим сбоем, а не эффектом.</p>\n</div>\n<div class=\"card\" style=\"flex:1 1 280px;\">\n<h3 class=\"card-title\">ABCD (многовариантные)</h3>\n<p style=\"font-size:13.5px;\">Сравнение нескольких альтернатив за один эксперимент. Плюс — выбрать лучший из набора. Минус — нужно <b>больше трафика</b> на группу и растёт риск ложных находок при множественных сравнениях.</p>\n</div>\n</div>"}, {"title": "Решение после теста", "summary": "Ситуация Решение Эффект +, устойчив и бизнес-значим внедрять, оценить масштаб и пост-релиз мониторинг Значим статистически, но мал для бизнеса не внедрять автоматом; сравнить с cost of change Незначим, но ДИ широкий тест недомощный; проверить выборку и MDE Уху", "terms": ["дизайн эксперимента"], "body": "<div class=\"tbl-wrap\"><table>\n<tr><th style=\"width:52%;\">Ситуация</th><th style=\"width:48%;\">Решение</th></tr>\n<tr><td>Эффект +, устойчив и бизнес-значим</td><td>внедрять, оценить масштаб и пост-релиз мониторинг</td></tr>\n<tr><td>Значим статистически, но мал для бизнеса</td><td>не внедрять автоматом; сравнить с cost of change</td></tr>\n<tr><td>Незначим, но ДИ широкий</td><td>тест недомощный; проверить выборку и MDE</td></tr>\n<tr><td>Ухудшились guardrail-метрики</td><td>не решать по primary; разобрать побочный ущерб</td></tr>\n<tr><td>Есть SRM / проблемы данных</td><td>не считать доказательным; пересмотреть</td></tr>\n</table></div><div class=\"formula\" style=\"margin-top:14px;\">\n      Модель мышления: Проблема → гипотеза → метрика → <b>дизайн эксперимента</b> → корректный запуск → анализ → продуктовое решение\n    </div>"}, {"title": "Самопроверка по A/B", "summary": "Вопросов: 6 Развернуть всё ", "terms": [], "body": "<div data-qa-group=\"\">\n</div>"}], "source": "Source A"}, {"id": "igmetrics", "title": "iGaming метрики", "icon": "∑", "stages": [{"title": "Базовые метрики (must-know)", "summary": "Фундамент, который спрашивают почти на любом iGaming-собесе. Знать расшифровку, формулу и смысл каждой.", "terms": ["Turnover", "GGR", "NGR", "Hold% / Margin", "RTP", "FTD", "DAU / WAU / MAU", "PAU", "New Players", "Stickiness", "ARPU", "ARPPU", "AMPPU", "LTV"], "body": "<p class=\"lead\">Фундамент, который спрашивают почти на любом iGaming-собесе. Знать расшифровку, формулу и смысл каждой.</p><div class=\"block-title\">Выручка</div><div class=\"tbl-wrap\"><table>\n<tr><th style=\"width:20%;\">Метрика</th><th style=\"width:30%;\">Расшифровка</th><th style=\"width:30%;\">Формула</th><th style=\"width:20%;\">Зачем</th></tr>\n<tr><td><b>Turnover</b> (оборот / handle)</td><td>суммарные ставки за период</td><td class=\"mono\">Σ Bets</td><td>объём игровой активности</td></tr>\n<tr><td><b>GGR</b></td><td>Gross Gaming Revenue — валовой доход</td><td class=\"mono\">Bets − Wins = Turnover × Hold%</td><td>«маржа казино» до расходов</td></tr>\n<tr><td><b>NGR</b></td><td>Net Gaming Revenue — чистый доход</td><td class=\"mono\">GGR − бонусы − fees провайдеров/платежей − налоги</td><td>реальная база прибыли и RevShare</td></tr>\n<tr><td><b>Hold% / Margin</b></td><td>удержание с оборота</td><td class=\"mono\">GGR / Turnover</td><td>спорт 5–10%; слоты 100%−RTP</td></tr>\n<tr><td><b>RTP</b></td><td>Return to Player — отдача игроку</td><td class=\"mono\">выплаты / ставки (%)</td><td>слоты обычно 94–97%</td></tr>\n</table></div><div class=\"block-title\" style=\"margin-top:10px;\">Игроки &amp; активность</div><div class=\"tbl-wrap\"><table>\n<tr><th style=\"width:20%;\">Метрика</th><th style=\"width:30%;\">Расшифровка</th><th style=\"width:30%;\">Формула / смысл</th><th style=\"width:20%;\">Зачем</th></tr>\n<tr><td><b>FTD</b></td><td>First Time Deposit — первый депозит</td><td class=\"mono\">первый успешный реал-депозит</td><td>лид → платящий игрок</td></tr>\n<tr><td><b>DAU / WAU / MAU</b></td><td>Daily / Weekly / Monthly Active Users</td><td class=\"mono\">уник. активные за день/неделю/месяц</td><td>размер активной базы</td></tr>\n<tr><td><b>PAU</b></td><td>Playing Active Users</td><td class=\"mono\">сделали ≥1 спин/ставку за период</td><td>реально играющая база</td></tr>\n<tr><td><b>New Players</b></td><td>новые игроки за период</td><td class=\"mono\">регистрации / новые FTD</td><td>приток аудитории</td></tr>\n<tr><td><b>Stickiness</b></td><td>липкость / привычка</td><td class=\"mono\">DAU / MAU</td><td>&gt;20% — сильно</td></tr>\n</table></div><div class=\"block-title\" style=\"margin-top:10px;\">Деньги на игрока &amp; удержание</div><div class=\"tbl-wrap\"><table>\n<tr><th style=\"width:20%;\">Метрика</th><th style=\"width:30%;\">Расшифровка</th><th style=\"width:30%;\">Формула</th><th style=\"width:20%;\">Зачем</th></tr>\n<tr><td><b>ARPU</b></td><td>Average Revenue Per User</td><td class=\"mono\">выручка / активные игроки</td><td>доход со среднего активного</td></tr>\n<tr><td><b>ARPPU</b></td><td>…Per Paying User</td><td class=\"mono\">депозиты / PAU</td><td>доход с платящего</td></tr>\n<tr><td><b>AMPPU</b></td><td>Avg Margin Per Paying User</td><td class=\"mono\">NGR / PAU</td><td>маржа с платящего</td></tr>\n<tr><td><b>LTV</b></td><td>Lifetime Value</td><td class=\"mono\">AMPPU × Lifetime</td><td>ценность игрока за «жизнь»</td></tr>\n<tr><td><b>CAC</b></td><td>Customer Acquisition Cost</td><td class=\"mono\">затраты / привлечённые игроки</td><td>цель LTV/CAC ≥ 3×</td></tr>\n<tr><td><b>Avg Deposit</b></td><td>средний депозит</td><td class=\"mono\">Σ депозитов / кол-во депозитов</td><td>платёжеспособность сегмента</td></tr>\n<tr><td><b>Retention / Churn Rate</b></td><td>удержание / отток</td><td class=\"mono\">активные тек. / активные пред. · Churn = 100%−Retention</td><td>здоровье базы</td></tr>\n</table></div><div class=\"note blue\"><b>Как это связано:</b> Turnover × Hold% = GGR; из GGR вычитаем бонусы/fees/налоги → NGR; NGR / PAU = AMPPU; AMPPU × Lifetime = LTV; и вся воронка окупается, когда <b>LTV / CAC ≥ 3×</b>. Это «скелет» unit-экономики iGaming.</div>"}, {"title": "Game Management", "summary": "Метрика Формула / смысл Бенчмарк / зачем Оборачиваемость депозита Bets Sum (real) / Deposits Sum 8–10 · драйвер GGR КПД слота Bets Count / Active Unique Users выше → больше GGR/игрока PAU / PAU (Real) сделали ≥1 спин за период / то же на реал база активной ауд", "terms": ["Оборачиваемость депозита", "КПД слота"], "body": "<div class=\"tbl-wrap\"><table>\n<tr><th style=\"width:26%;\">Метрика</th><th style=\"width:44%;\">Формула / смысл</th><th style=\"width:30%;\">Бенчмарк / зачем</th></tr>\n<tr><td><b>Оборачиваемость депозита</b></td><td class=\"mono\">Bets Sum (real) / Deposits Sum</td><td class=\"bnum\">8–10 · драйвер GGR</td></tr>\n<tr><td><b>КПД слота</b></td><td class=\"mono\">Bets Count / Active Unique Users</td><td class=\"bnum\">выше → больше GGR/игрока</td></tr>\n<tr><td>PAU / PAU (Real)</td><td class=\"mono\">сделали ≥1 спин за период / то же на реал</td><td>база активной аудитории</td></tr>\n<tr><td>Game Engagement Rate</td><td class=\"mono\">Session Count / PAU</td><td>глубина вовлечения</td></tr>\n<tr><td>Win Rate</td><td class=\"mono\">выигрышные ставки / все ставки</td><td>ощущение «отдачи»</td></tr>\n<tr><td>Volatility Index (game)</td><td class=\"mono\">STD(Bet Wins) / AVG(Bet Wins)</td><td>разброс выигрышей</td></tr>\n<tr><td>Top Games Share</td><td class=\"mono\">% GGR/ставок на топ-10 игр</td><td>концентрация контента</td></tr>\n<tr><td>Session Length AVG</td><td class=\"mono\">средняя длительность сессии</td><td>ранний маркер выгорания слота</td></tr>\n<tr><td>Game Switch Rate</td><td class=\"mono\">смен игр за сессию</td><td>когорта «бегунков» → персонализация</td></tr>\n<tr><td>Scroll Depth</td><td class=\"mono\">позиция скролла / длина контента</td><td>где отваливается в лобби/лендинге</td></tr>\n<tr><td>Bet2FTD</td><td class=\"mono\">ставок до 1-го депозита</td><td>важно при бездеп-бонусах</td></tr>\n<tr><td>Avg Time to First Bet</td><td class=\"mono\">рег → первая ставка</td><td>насколько «горячий» игрок</td></tr>\n</table></div>"}, {"title": "Bonus Management", "summary": "Метрика Формула / смысл Бенчмарк / зачем Bonus Cap выдано бонусов, % от GGR 15–30% · зависит от целей Bonus Activation Rate % игроков, активировавших бонус интерес к промо Bonus Conversion Rate % игроков, отыгравших бонус реальная ценность бонуса Avg Wagering ", "terms": ["Bonus Cap"], "body": "<div class=\"tbl-wrap\"><table>\n<tr><th style=\"width:26%;\">Метрика</th><th style=\"width:44%;\">Формула / смысл</th><th style=\"width:30%;\">Бенчмарк / зачем</th></tr>\n<tr><td><b>Bonus Cap</b></td><td class=\"mono\">выдано бонусов, % от GGR</td><td class=\"bnum\">15–30% · зависит от целей</td></tr>\n<tr><td>Bonus Activation Rate</td><td class=\"mono\">% игроков, активировавших бонус</td><td>интерес к промо</td></tr>\n<tr><td>Bonus Conversion Rate</td><td class=\"mono\">% игроков, отыгравших бонус</td><td>реальная ценность бонуса</td></tr>\n<tr><td>Avg Wagering Multiplier</td><td class=\"mono\">средний вагер на проекте</td><td>жёсткость условий</td></tr>\n<tr><td>Avg Time to Clear Bonus</td><td class=\"mono\">среднее время отыгрыша</td><td>трение бонуса</td></tr>\n<tr><td>Sticky vs Non-Sticky</td><td class=\"mono\">доля липких/нелипких бонусов</td><td>липкий = нельзя вывести до отыгрыша</td></tr>\n<tr><td>Bonus Retention Effect</td><td class=\"mono\">ретен когорты, получившей бонус</td><td>реальный эффект на удержание</td></tr>\n<tr><td>Bonus Expiration Rate</td><td class=\"mono\">истёкшие / выданные бонусы</td><td>невзятое промо</td></tr>\n<tr><td>Max Bonus Exposure</td><td class=\"mono\">пиковая бонусная нагрузка в моменте</td><td>риск-контроль по дням</td></tr>\n<tr><td>Bonus Abuse Cluster Count</td><td class=\"mono\">связанные бонус-хантеры</td><td>Бразилия/Африка/СНГ, Tier-2</td></tr>\n</table></div>"}, {"title": "Финансовые (специфичные)", "summary": "Метрика Формула / смысл Бенчмарк / зачем InOut / InOut % Депозиты − Выводы · % выводов от депозитов 25–35% · ликвидность/стратегия AMPPU NGR / PAU маржа с активного платящего Cash Ratio кэш на балансах / GGR контроль ликвидности Avg Cashout Time среднее время ", "terms": ["InOut", "InOut %", "AMPPU"], "body": "<div class=\"tbl-wrap\"><table>\n<tr><th style=\"width:26%;\">Метрика</th><th style=\"width:44%;\">Формула / смысл</th><th style=\"width:30%;\">Бенчмарк / зачем</th></tr>\n<tr><td><b>InOut</b> / <b>InOut %</b></td><td class=\"mono\">Депозиты − Выводы · % выводов от депозитов</td><td class=\"bnum\">25–35% · ликвидность/стратегия</td></tr>\n<tr><td><b>AMPPU</b></td><td class=\"mono\">NGR / PAU</td><td>маржа с активного платящего</td></tr>\n<tr><td>Cash Ratio</td><td class=\"mono\">кэш на балансах / GGR</td><td>контроль ликвидности</td></tr>\n<tr><td>Avg Cashout Time</td><td class=\"mono\">среднее время на вывод</td><td>доверие и жалобы</td></tr>\n<tr><td>Failed Deposit Rate</td><td class=\"mono\">неуспешные / все депозиты</td><td>потери на кассе</td></tr>\n<tr><td>Deposit → Real Play</td><td class=\"mono\">% депозитов, реально ушедших в ставки</td><td>«мёртвые» депозиты</td></tr>\n<tr><td>CAC (правило)</td><td class=\"mono\">затраты / привлечённые × LTV(год)</td><td class=\"bnum\">целевое 1:3</td></tr>\n</table></div>"}, {"title": "Тайминги воронки & маркетинг", "summary": "Метрика Формула / смысл Зачем FTD2RD конверсия в повторный депозит переход к активной когорте Repeat Rate повторные депозиты / FD плотность повторных депозитов Time to 2nd dep FTD → RD скорость входа в цикл FTD / RD Share in Revenue % дохода от FTD / повторных", "terms": [], "body": "<div class=\"tbl-wrap\"><table>\n<tr><th style=\"width:26%;\">Метрика</th><th style=\"width:44%;\">Формула / смысл</th><th style=\"width:30%;\">Зачем</th></tr>\n<tr><td>FTD2RD</td><td class=\"mono\">конверсия в повторный депозит</td><td>переход к активной когорте</td></tr>\n<tr><td>Repeat Rate</td><td class=\"mono\">повторные депозиты / FD</td><td>плотность повторных депозитов</td></tr>\n<tr><td>Time to 2nd dep</td><td class=\"mono\">FTD → RD</td><td>скорость входа в цикл</td></tr>\n<tr><td>FTD / RD Share in Revenue</td><td class=\"mono\">% дохода от FTD / повторных</td><td>откуда реально деньги</td></tr>\n<tr><td>ROI по каналам</td><td class=\"mono\">прибыль по игрокам канала / затраты</td><td>какой трафик окупается</td></tr>\n<tr><td>CPR / CPD</td><td class=\"mono\">касты / рег · касты / FTD</td><td>стоимость шагов воронки</td></tr>\n<tr><td>Promo Engagement Rate</td><td class=\"mono\">% взаимодействовавших с промо</td><td>отклик на коммуникации</td></tr>\n</table></div>"}, {"title": "Retention / VIP", "summary": "Метрика Формула / смысл Зачем Whales / Top 1% GGR Share доход от топ-1% игроков вклад хайроллеров (сильно от ГЕО) VIP Retention D30 % VIP, вернувшихся через 30 дн. мастхэв для VIP-отдела Velocity of Spend скорость слива депозита ($/мин) триггерные бонусы и цеп", "terms": ["Whales / Top 1% GGR Share"], "body": "<div class=\"tbl-wrap\"><table>\n<tr><th style=\"width:26%;\">Метрика</th><th style=\"width:44%;\">Формула / смысл</th><th style=\"width:30%;\">Зачем</th></tr>\n<tr><td><b>Whales / Top 1% GGR Share</b></td><td class=\"mono\">доход от топ-1% игроков</td><td>вклад хайроллеров (сильно от ГЕО)</td></tr>\n<tr><td>VIP Retention D30</td><td class=\"mono\">% VIP, вернувшихся через 30 дн.</td><td>мастхэв для VIP-отдела</td></tr>\n<tr><td class=\"mono\">скорость слива депозита ($/мин)</td><td>триггерные бонусы и цепочки</td></tr>\n<tr><td>Deposit Size Trend</td><td class=\"mono\">динамика среднего депозита сегмента</td><td>рост/просадка VIP</td></tr>\n<tr><td>Return Rate</td><td class=\"mono\">% вернувшихся после паузы</td><td>эффект win-back</td></tr>\n<tr><td>Time to Churn</td><td class=\"mono\">среднее время до ухода</td><td>окно для удержания</td></tr>\n<tr><td>Avg Lifetime / Play Days</td><td class=\"mono\">дней жизни · активных дней</td><td>горизонт LTV</td></tr>\n</table></div>"}, {"title": "Юр. ограничения / Responsible Gaming", "summary": "Особенно важны на сильно регулируемых ГЕО — и часто спрашивают, чтобы проверить зрелость.", "terms": ["Сигналы, что слот умирает", "раньше"], "body": "<p class=\"lead\">Особенно важны на сильно регулируемых ГЕО — и часто спрашивают, чтобы проверить зрелость.</p><div class=\"tbl-wrap\"><table>\n<tr><th style=\"width:34%;\">Метрика</th><th>Смысл</th></tr>\n<tr><td>Self-Exclusion Rate</td><td>% игроков, инициировавших самоисключение</td></tr>\n<tr><td>Limit Usage Rate</td><td>% игроков, установивших лимиты</td></tr>\n<tr><td>Account Reopen Rate</td><td>возвраты после блокировки/исключения</td></tr>\n<tr><td>Session Time &gt; 5h</td><td>сессии с переигрыванием</td></tr>\n<tr><td>Deposit Source Mismatch</td><td>страна IP ≠ страна платёжки</td></tr>\n</table></div><div class=\"note green\" style=\"margin-top:12px;\">\n<b>Сигналы, что слот умирает</b> (даже при нормальном GGR): PAU падает 7+ дней · CTR из лобби ↓ · Session Length сокращается · Unique Bets на игрока ↓ · средняя ставка (Bet Avg) ↓ · слабый Slot Retention. CTR и Session Length проседают <b>раньше</b> PAU — это самые ранние маркеры.\n    </div>"}, {"title": "Самопроверка", "summary": "Вопросов: 4 Развернуть всё ", "terms": [], "body": "<div data-qa-group=\"\">\n</div>"}], "source": "Source A"}, {"id": "bonus", "title": "Бонусы & игры", "icon": "◇", "stages": [{"title": "Философия бонусов", "summary": "Тренд — уход от вагеров к прозрачной системе на базе суммы ставок (кроме Welcome-пакета). Игрок должен понимать ценность бонуса без «читания мелкого шрифта». Массмаркет по-прежнему часто перформит на вагерах — знать оба подхода обязательно.", "terms": ["уход от вагеров", "суммы ставок"], "body": "<div class=\"note green\">\n      Тренд — <b>уход от вагеров</b> к прозрачной системе на базе <b>суммы ставок</b> (кроме Welcome-пакета). Игрок должен понимать ценность бонуса без «читания мелкого шрифта». Массмаркет по-прежнему часто перформит на вагерах — знать оба подхода обязательно.\n    </div>"}, {"title": "Четыре типа бонусов", "summary": "1 Welcome Pack Прозрачный подход: бонус к балансу только на 1-й депозит, до ~10% от депа с мин/макс лимитами; чем выше деп, тем «визуально» выше приз. Массмаркет: лесенка до 4-го депозита, от 100% к депозиту, вагер ~30× с ограничением отыгрыша. Антифрод решает", "terms": ["Прозрачный подход", "Массмаркет", "10 уровней", "Нематериальные плюшки", "Рейбэк от суммы ставок", "Кэшбэк от потерь"], "body": "<div class=\"card\">\n<div class=\"card-head\"><div class=\"stage-badge\" style=\"background:#2b3a78;\">1</div><h3 class=\"card-title\">Welcome Pack</h3></div>\n<ul class=\"tips\">\n<li><b>Прозрачный подход:</b> бонус к балансу только на 1-й депозит, до ~10% от депа с мин/макс лимитами; чем выше деп, тем «визуально» выше приз.</li>\n<li><b>Массмаркет:</b> лесенка до 4-го депозита, от 100% к депозиту, вагер ~30× с ограничением отыгрыша.</li>\n<li>Антифрод решается математикой и сильной разработкой, а не ужесточением условий.</li>\n</ul>\n</div><div class=\"card\">\n<div class=\"card-head\"><div class=\"stage-badge\" style=\"background:#31708e;\">2</div><h3 class=\"card-title\">Reload — через систему уровней</h3></div>\n<ul class=\"tips\">\n<li>Не менее <b>10 уровней</b>; уровень — от суммы ставок за месяц; удержание уровня — 50% от KPI уровня.</li>\n<li>Ежемесячный бонус за уровень (без вагера), растёт с уровнем.</li>\n\n</ul>\n</div><div class=\"card\">\n<div class=\"card-head\"><div class=\"stage-badge\" style=\"background:#0d9488;\">3</div><h3 class=\"card-title\">Кэшбэк / Рейбэк</h3></div>\n<ul class=\"tips\">\n<li><b>Рейбэк от суммы ставок</b> — прозрачнее для игрока: без вагера/лимитов, раз в неделю, только по слотам, работает и как reload.</li>\n<li><b>Кэшбэк от потерь:</b> вагер не выше ×10 и быстро уменьшать лесенкой; выдавать по кнопке «Забрать», не авто; ставить лимит на макс-выплату.</li>\n</ul>\n</div><div class=\"card\">\n<div class=\"card-head\"><div class=\"stage-badge\" style=\"background:#10b981;\">4</div><h3 class=\"card-title\">Retention-бонус</h3></div>\n<ul class=\"tips\">\n<li>Ежедневный, без вагера, 3 уровня от суммы ставок (можно забрать все).</li>\n<li>Альтернатива — привязка к депозиту: день недели, кол-во/частота/сумма депозитов, метод пополнения.</li>\n<li>Коллаборации с провайдерами снижают касты.</li>\n</ul>\n</div>"}, {"title": "Типы бонусного баланса (кейс-тест)", "summary": "Тестировалось на рынке Африки, на Welcome (1–3 деп) + reload.", "terms": ["Заблокированный", "Распространённый", "Гибридный"], "body": "<p class=\"lead\">Тестировалось на рынке Африки, на Welcome (1–3 деп) + reload.</p><div class=\"tbl-wrap\"><table>\n<tr><th style=\"width:20%;\">Тип</th><th style=\"width:44%;\">Логика</th><th style=\"width:36%;\">Итог</th></tr>\n<tr><td><b>Заблокированный</b> («нафталин»)</td><td>бонус-баланс заблокирован, отыгрыш только с реала, потом падает на реал</td><td class=\"bnum\">жалобы «скам», конверсия в 4-й деп ↓, churn +~20% <span class=\"pill bad\">плохо</span></td></tr>\n<tr><td><b>Распространённый</b></td><td>отыгрыш сперва с реала, кончился — списывается бонус; отыгран — падает на реал</td><td class=\"bnum\">конверт ~бенч <span class=\"pill good\">рабочий</span></td></tr>\n<tr><td><b>Гибридный</b> 50/50</td><td>списание и выигрыш делятся 50/50 реал/бонус</td><td class=\"bnum\">конверт ↑, но легче абузится, маржа ниже <span class=\"pill warn\">спорный</span></td></tr>\n</table></div>"}, {"title": "Экономика бонуса", "summary": "Контроль вагера через блэклисты игр: понижение коэффициента отыгрыша, полная блокировка, по волатильности/лимитам/категориям/типу ставки. Низкий вагер безопасен только при управляемых блэклистах — иначе бонус легко «откручивают».", "terms": ["$5", "Контроль вагера через блэклисты игр"], "body": "<div class=\"formula\">\n      Welcome Pack Costs = AVG FTD × % бонуса  (пример: $50 × 10% = <b>$5</b> на игрока)<br/>\n      Нагрузку на GGR всегда считаем ДО релиза — по шансам, лимитам и сегментам. Вагер ×1 — «честный» ориентир прозрачной модели.\n    </div><div class=\"note\"><b>Контроль вагера через блэклисты игр:</b> понижение коэффициента отыгрыша, полная блокировка, по волатильности/лимитам/категориям/типу ставки. Низкий вагер безопасен только при управляемых блэклистах — иначе бонус легко «откручивают».</div>"}, {"title": "Игровая монетизация", "summary": "Live RTP — витрина «горячих/холодных» слотов в реальном времени: добавляет открытости и иллюзию контроля. Усилители: поиск по игре, интерактивные ивенты («поймай мультипликатор дня»), шеринг ячейки, связка с ачивками. Видео-занос в лобби (5–7 сек автоплей) под", "terms": ["Оборачиваемость депозита 8–10", "КПД слота", "Bonus Buy vs фриспины", "GGR > $10M/мес", "RTP 97–98%", "Live RTP", "Видео-занос в лобби"], "body": "<div class=\"grid2\">\n<div><div class=\"block-title\">Рычаги GGR через игры</div>\n<ul class=\"tips\">\n<li><b>Оборачиваемость депозита 8–10</b> — растить через лояльность и слоты с высоким КПД.</li>\n<li><b>КПД слота</b> для приоритизации лобби; провайдеры под ГЕО (PGsoft, PlaynGO, EGT, 1spin4win и др.).</li>\n<li><b>Bonus Buy vs фриспины:</b> Bonus Buy ценят опытные игроки и хайроллеры → выше вовлечение и ARPU.</li>\n</ul></div>\n<div><div class=\"block-title\">Брендовые игры</div>\n<ul class=\"tips\">\n<li>Начинать при <b>GGR &gt; $10M/мес</b>; типы: live-столы, слоты, инхаус.</li>\n<li>Бренд-слот — с топ-10 провайдером проекта, <b>RTP 97–98%</b>, кастомизация (экран, маскот, бонуска).</li>\n<li>Продумывать SMM/промо под релиз; краш/инстант — лучше инхаус.</li>\n</ul></div>\n</div>"}, {"title": "Самопроверка", "summary": "Вопросов: 4 Развернуть всё ", "terms": [], "body": "<div data-qa-group=\"\">\n</div>"}], "source": "Source A"}, {"id": "retention", "title": "Retention & CJM", "icon": "↻", "stages": [{"title": "Программа лояльности & геймификация", "summary": "Гейм-механики: миссии, колесо фортуны (8 секторов, прогрессия уровней от размера депа), ачивки, коллекционные концепты («Карта удачи» — 5 карт с редкостью Common/Rare/Epic, комбо-бонусы, альбом). Цель — поднять частоту и длину сессий, а экономика управляется ш", "terms": ["2–3 дня", "0.05–0.3% месячного GGR", "20%", "×1.5", "200–500 призов/день", "Гейм-механики"], "body": "<div class=\"grid2\">\n<div class=\"card\" style=\"flex:1 1 280px;\">\n<h3 class=\"card-title\">Турниры</h3>\n<ul class=\"tips\">\n<li>Длительность 1–7 дн., оптимум <b>2–3 дня</b>.</li>\n<li>Бюджет ~<b>0.05–0.3% месячного GGR</b>.</li>\n<li>KPI: сумма ставок, сумма мультипликаторов.</li>\n<li>Лидерборд 20–30 позиций; главный приз ≥ <b>20%</b> фонда.</li>\n</ul>\n</div>\n<div class=\"card\" style=\"flex:1 1 280px;\">\n<h3 class=\"card-title\">Drops</h3>\n<ul class=\"tips\">\n<li>Длительность 3–7 дн.; бюджет ~<b>×1.5</b> к турниру.</li>\n<li>Хорошо заходят по новинкам и тематике (Хэллоуин и т.п.).</li>\n<li>Мин. ставка 20–40% от средней; <b>200–500 призов/день</b>.</li>\n<li>Инхаус + локальные ивенты дают буст суммы ставок 20%+.</li>\n</ul>\n</div>\n</div><div class=\"note\"><b>Гейм-механики:</b> миссии, колесо фортуны (8 секторов, прогрессия уровней от размера депа), ачивки, коллекционные концепты («Карта удачи» — 5 карт с редкостью Common/Rare/Epic, комбо-бонусы, альбом). Цель — поднять частоту и длину сессий, а экономика управляется шансами и лимитами под сегменты.</div>"}, {"title": "Продуктовые коммуникации", "summary": "Инструменты общения с игроком на самом продукте. У каждого — своя задача.", "terms": ["Баннеры", "Попапы", "Моб. плашки", "Уведомления", "Чат на сайте", "Активные кнопки"], "body": "<p class=\"lead\">Инструменты общения с игроком на самом продукте. У каждого — своя задача.</p><div class=\"tbl-wrap\"><table>\n<tr><th style=\"width:24%;\">Инструмент</th><th style=\"width:40%;\">Особенности</th><th style=\"width:36%;\">Задача</th></tr>\n<tr><td><b>Баннеры</b></td><td>полностью кликабельны, визуал+УТП, ручное перелистывание</td><td>Welcome, ивенты, релизы</td></tr>\n<tr><td><b>Попапы</b></td><td>только на критичных этапах CJM/по триггерам, не спамить</td><td>апсейл, объяснения, ситуативные бонусы</td></tr>\n<tr><td><b>Моб. плашки</b></td><td>не высокие, одна на экран, закрываемые</td><td>APK/вебвью, мессенджеры</td></tr>\n<tr><td><b>Уведомления</b></td><td>продумать состояния, не спамить</td><td>финоперации, бонусы, ошибки</td></tr>\n<tr><td><b>Чат на сайте</b></td><td>закреп + авто-рассылка от проекта</td><td>крупные ивенты, объявления</td></tr>\n<tr><td><b>Активные кнопки</b></td><td>иконка у кошелька / кастом + анимация</td><td>сезонные промо, перелив в APK</td></tr>\n</table></div>"}, {"title": "CRO-рычаги ранней воронки", "summary": "Click2Reg Форма реги в один экран на мобилке, без попапов поверх неё; можно прямо на главной. Позиционирование: конкретные цифры вместо процентов — «up to $4000» , а не «400%». Промокод в форме (кнопка «вставить» / автоподстановка по UTM). Пролив сразу на форм", "terms": ["один экран", "«up to $4000»", "фаст-кнопки", "Быстрый депозит"], "body": "<div class=\"grid2\">\n<div><div class=\"block-title\">Click2Reg</div>\n<ul class=\"tips\">\n<li>Форма реги в <b>один экран</b> на мобилке, без попапов поверх неё; можно прямо на главной.</li>\n<li>Позиционирование: конкретные цифры вместо процентов — <b>«up to $4000»</b>, а не «400%».</li>\n<li>Промокод в форме (кнопка «вставить» / автоподстановка по UTM).</li>\n<li>Пролив сразу на форму / авто-открытие формы / iframe на лендинге.</li>\n</ul></div>\n<div><div class=\"block-title\">Reg2FTD</div>\n<ul class=\"tips\">\n<li>Экспериментировать с кассиром: <b>фаст-кнопки</b>, лимиты, апсейл, таймеры (прирост до ~5% на объёмах окупается).</li>\n<li><b>Быстрый депозит</b> плашкой с любой страницы (сумма + метод), автоподбор реквизита.</li>\n<li>Модалки на все виды неуспешной оплаты + кросс-селл при ошибке.</li>\n<li>Ошибка «error» без смысла = провал; каждое сообщение должно направлять игрока.</li>\n</ul></div>\n</div>"}, {"title": "Сегментация & путь игрока", "summary": "Психология оттока. Игроки чаще уходят при быстром сливе баланса, серии проигрышей или крупной потере за сессию — и реже после выигрыша. Отсюда сильная гипотеза: поддерживать игрока (бонусом/коммуникацией) именно в затяжном сливе (по Velocity of Spend), а не то", "terms": ["Незарег / зарег", "1-й депозит", "2–4-й депозит", "4–12-й депозит", "Психология оттока", "реже"], "body": "<div class=\"tbl-wrap\"><table>\n<tr><th style=\"width:26%;\">Когорта</th><th>Типичные продуктовые проблемы</th></tr>\n<tr><td><b>Незарег / зарег</b></td><td>трение формы и KYC, непонятный первый экран лобби, нет ясного «след. шага»</td></tr>\n<tr><td><b>1-й депозит</b></td><td>не почувствовал ценность бонуса, платёжное трение, нет причины для 2-го депа</td></tr>\n<tr><td><b>2–4-й депозит</b></td><td>слабый reload, отсутствие привычки, welcome «выветрился» без reload-механик</td></tr>\n<tr><td><b>4–12-й депозит</b></td><td>переход в лояльную базу/VIP, риск оттока при просадке чека и частоты</td></tr>\n</table></div>"}, {"title": "Самопроверка", "summary": "Вопросов: 4 Развернуть всё ", "terms": [], "body": "<div data-qa-group=\"\">\n</div>"}], "source": "Source A"}, {"id": "crm", "title": "CRM", "icon": "✉", "stages": [{"title": "Что это и зачем", "summary": "CRM (Customer Relationship Management) в iGaming = движок retention и монетизации : сегментация игроков, триггерные кампании и мультиканальные коммуникации по всему пути игрока. Цель — не «разослать акцию», а поднять LTV и снизить отток через нужное сообщение ", "terms": ["CRM (Customer Relationship Management)", "retention и монетизации", "поднять LTV и снизить отток", "Onboarding", "Retention", "Reactivation", "Монетизация", "Сегментация", "Триггеры", "Каналы", "A/B и uplift"], "body": "<div class=\"note green\">\n<b>CRM (Customer Relationship Management)</b> в iGaming = движок <b>retention и монетизации</b>: сегментация игроков, триггерные кампании и мультиканальные коммуникации по всему пути игрока. Цель — не «разослать акцию», а <b>поднять LTV и снизить отток</b> через нужное сообщение нужному сегменту в нужный момент.\n    </div><div class=\"grid2\">\n<div><div class=\"block-title\">Задачи CRM</div>\n<ul class=\"tips\">\n<li><b>Onboarding:</b> довести новорега до FTD и 2-го депозита.</li>\n<li><b>Retention:</b> удерживать привычку, растить частоту депозитов.</li>\n<li><b>Reactivation:</b> возвращать «спящих» (20–30% при таргетинге).</li>\n<li><b>Монетизация:</b> reload/ситуативные офферы, VIP-nurture.</li>\n</ul></div>\n<div><div class=\"block-title\">Из чего состоит</div>\n<ul class=\"tips\">\n<li><b>Сегментация:</b> по стадии, поведению, ценности, ГЕО.</li>\n<li><b>Триггеры:</b> событийные сценарии (депозит, слив, пауза).</li>\n<li><b>Каналы:</b> email, push, SMS, on-site, мессенджеры.</li>\n<li><b>A/B и uplift:</b> замер прироста vs контрольная группа.</li>\n</ul></div>\n</div>"}, {"title": "Ключевые сценарии (flows)", "summary": "Сценарий Триггер Цель Welcome journey регистрация без FTD довести до первого депозита FTD → 2nd deposit сделал FTD второй депозит, вход в цикл Churn-prevention ранние сигналы (частота/чек ↓) удержать до ухода Win-back «тишина» N дней реактивация спящего VIP-nu", "terms": [], "body": "<div class=\"tbl-wrap\"><table>\n<tr><th style=\"width:26%;\">Сценарий</th><th style=\"width:40%;\">Триггер</th><th style=\"width:34%;\">Цель</th></tr>\n<tr><td>Welcome journey</td><td>регистрация без FTD</td><td>довести до первого депозита</td></tr>\n<tr><td>FTD → 2nd deposit</td><td>сделал FTD</td><td>второй депозит, вход в цикл</td></tr>\n<tr><td>Churn-prevention</td><td>ранние сигналы (частота/чек ↓)</td><td>удержать до ухода</td></tr>\n<tr><td>Win-back</td><td>«тишина» N дней</td><td>реактивация спящего</td></tr>\n<tr><td>VIP-nurture</td><td>рост ценности/чека</td><td>удержание ядра выручки</td></tr>\n<tr><td>Downswing-support</td><td>поддержка в затяжном сливе</td></tr>\n</table></div>"}, {"title": "Real-time — почему критично", "summary": "Батч-CRM обновляет данные ночью и упускает главное окно — первую сессию. Триггер на депозит, пока игрок ещё в приложении, работает в разы лучше, чем оффер «завтра из ночного батча». Отсюда тренд на real-time движки и единый data-слой (CDP + исполнение).", "terms": [], "body": "<div class=\"note\"><b>Батч-CRM обновляет данные ночью и упускает главное окно — первую сессию.</b> Триггер на депозит, пока игрок ещё в приложении, работает в разы лучше, чем оффер «завтра из ночного батча». Отсюда тренд на real-time движки и единый data-слой (CDP + исполнение).</div>"}, {"title": "Метрики CRM & инструменты", "summary": "Что мерить Campaign Conversion, Promo Engagement Rate. Reactivation Rate, Churn Rate. Deliverability / Open / CTR по каналам. Incremental NGR (uplift vs контроль) — главный судья. Инструменты рынка Optimove, Xtremepush, Braze, Solitics, customer.io. Связка с C", "terms": ["Incremental NGR", "Антипаттерн"], "body": "<div class=\"grid2\">\n<div><div class=\"block-title\">Что мерить</div>\n<ul class=\"tips\">\n<li>Campaign Conversion, Promo Engagement Rate.</li>\n<li>Reactivation Rate, Churn Rate.</li>\n<li>Deliverability / Open / CTR по каналам.</li>\n<li><b>Incremental NGR</b> (uplift vs контроль) — главный судья.</li>\n</ul></div>\n<div><div class=\"block-title\">Инструменты рынка</div>\n<ul class=\"tips\">\n<li>Optimove, Xtremepush, Braze, Solitics, customer.io.</li>\n<li>Связка с CDP/сегментацией и лайфсайкл-движком.</li>\n<li><b>Антипаттерн:</b> ковровые рассылки на «100500 сегментов» = лечение симптомов, а не стратегия.</li>\n</ul></div>\n</div>"}, {"title": "Самопроверка", "summary": "Вопросов: 3 Развернуть всё ", "terms": [], "body": "<div data-qa-group=\"\">\n</div>"}], "source": "Source A"}, {"id": "kyc", "title": "KYC & Compliance", "icon": "✓", "stages": [{"title": "Что это и зачем", "summary": "KYC (Know Your Customer) — подтверждение личности, возраста и источника средств игрока. Нужен для: лицензии/регуляторики , борьбы с фродом и мультиаккаунтами , ответственной игры (18+), защиты от chargeback и отмывания (AML).", "terms": ["KYC (Know Your Customer)", "лицензии/регуляторики", "фродом и мультиаккаунтами", "ответственной игры", "chargeback"], "body": "<div class=\"note green\">\n<b>KYC (Know Your Customer)</b> — подтверждение личности, возраста и источника средств игрока. Нужен для: <b>лицензии/регуляторики</b>, борьбы с <b>фродом и мультиаккаунтами</b>, <b>ответственной игры</b> (18+), защиты от <b>chargeback</b> и отмывания (AML).\n    </div>"}, {"title": "Компоненты", "summary": "Проверка Что подтверждает Identity verification документ (паспорт/ID) + селфи/liveness Age verification 18+ (или локальный порог) Proof of Address адрес проживания (для лимитов/выводов) Source of Funds / Wealth происхождение средств (крупные депозиты, VIP) PEP", "terms": [], "body": "<div class=\"tbl-wrap\"><table>\n<tr><th style=\"width:30%;\">Проверка</th><th>Что подтверждает</th></tr>\n<tr><td>Identity verification</td><td>документ (паспорт/ID) + селфи/liveness</td></tr>\n<tr><td>Age verification</td><td>18+ (или локальный порог)</td></tr>\n<tr><td>Proof of Address</td><td>адрес проживания (для лимитов/выводов)</td></tr>\n<tr><td>Source of Funds / Wealth</td><td>происхождение средств (крупные депозиты, VIP)</td></tr>\n<tr><td>PEP &amp; Sanctions screening</td><td>публичные лица и санкционные списки</td></tr>\n<tr><td>Ongoing monitoring</td><td>мониторинг транзакций и подозрительной активности</td></tr>\n</table></div>"}, {"title": "Продуктовый трейд-офф", "summary": "KYC vs конверсия. Тяжёлый KYC на входе рушит Reg2FTD — плохо спроектированные форма и KYC съедают 30–50% будущих депозиторов. Решение — risk-based / progressive KYC : лёгкая проверка на входе, усиленная (EDD) — к выводу, лимиту или на high-risk/high-value. Вер", "terms": ["KYC vs конверсия", "30–50%", "risk-based / progressive KYC", "Базовый", "Усиленный (EDD)", "Автоверификация", "KYC pass rate"], "body": "<div class=\"note\"><b>KYC vs конверсия.</b> Тяжёлый KYC на входе рушит Reg2FTD — плохо спроектированные форма и KYC съедают <b>30–50%</b> будущих депозиторов. Решение — <b>risk-based / progressive KYC</b>: лёгкая проверка на входе, усиленная (EDD) — к выводу, лимиту или на high-risk/high-value. Верификацию показывать ценность раньше, документы просить позже.</div><div class=\"grid2\">\n<div><div class=\"block-title\">Уровни</div>\n<ul class=\"tips\">\n<li><b>Базовый:</b> на регистрации/первом выводе.</li>\n<li><b>Усиленный (EDD):</b> для крупных сумм, VIP, high-risk ГЕО.</li>\n<li><b>Автоверификация:</b> OCR + liveness + базы; fallback — ручная проверка.</li>\n</ul></div>\n<div><div class=\"block-title\">KYC-метрики</div>\n<ul class=\"tips\">\n<li><b>KYC pass rate</b> &gt; 80–90%.</li>\n<li>Time-to-verify, drop-off на KYC.</li>\n<li>Manual review rate, false rejection rate.</li>\n</ul></div>\n</div>"}, {"title": "Связки и провайдеры", "summary": "Экосистема AML: transaction monitoring, source of funds, SAR. Responsible Gaming: self-exclusion, лимиты, cooldown. Anti-fraud: device fingerprint, multi-accounting, Deposit Source Mismatch. KYC-провайдеры Sumsub, Jumio, Onfido, Veriff, iDenfy. Pay-N-Play (Tru", "terms": ["AML", "Responsible Gaming", "Anti-fraud", "Pay-N-Play (Trustly)"], "body": "<div class=\"grid2\">\n<div><div class=\"block-title\">Экосистема</div>\n<ul class=\"tips\">\n<li><b>AML:</b> transaction monitoring, source of funds, SAR.</li>\n<li><b>Responsible Gaming:</b> self-exclusion, лимиты, cooldown.</li>\n<li><b>Anti-fraud:</b> device fingerprint, multi-accounting, Deposit Source Mismatch.</li>\n</ul></div>\n<div><div class=\"block-title\">KYC-провайдеры</div>\n<ul class=\"tips\">\n<li>Sumsub, Jumio, Onfido, Veriff, iDenfy.</li>\n<li><b>Pay-N-Play (Trustly):</b> подтягивает верифицированный KYC из банка прямо в депозит — регистрация без формы, выше FTD-конверт (Сев./Центр. Европа).</li>\n</ul></div>\n</div>"}, {"title": "Самопроверка", "summary": "Вопросов: 3 Развернуть всё ", "terms": [], "body": "<div data-qa-group=\"\">\n</div>"}], "source": "Source A"}, {"id": "geo", "title": "Новый GEO", "icon": "◎", "stages": [{"title": "Порядок выхода на рынок", "summary": "Шаг Что решаем 1. Research размер рынка, конкуренты (чек-лист 87 пунктов), sentiment в WhatsApp/Telegram, SimilarWeb/Sensor Tower 2. Регуляторика статус (regulated/grey/black), лицензия (локальная vs Curacao/MGA), налоги, ограничения рекламы 3. Платёжки локаль", "terms": ["1. Research", "2. Регуляторика", "3. Платёжки", "4. Локализация", "5. Продукт", "6. Контент", "7. CRM/Retention", "8. Launch & iterate"], "body": "<div class=\"tbl-wrap\"><table>\n<tr><th style=\"width:22%;\">Шаг</th><th>Что решаем</th></tr>\n<tr><td><b>1. Research</b></td><td>размер рынка, конкуренты (чек-лист 87 пунктов), sentiment в WhatsApp/Telegram, SimilarWeb/Sensor Tower</td></tr>\n<tr><td><b>2. Регуляторика</b></td><td>статус (regulated/grey/black), лицензия (локальная vs Curacao/MGA), налоги, ограничения рекламы</td></tr>\n<tr><td><b>3. Платёжки</b></td><td>локальные методы под ГЕО (см. ниже) — критичный пункт</td></tr>\n<tr><td><b>4. Локализация</b></td><td>язык носителями, валюта, дизайн, форматы (интерфейс, финансы, рег, поддержка, бонусы…)</td></tr>\n<tr><td><b>5. Продукт</b></td><td>мобайл-first, лёгкий APK/PWA, low-data, скорость под слабый интернет</td></tr>\n<tr><td><b>6. Контент</b></td><td>слоты/провайдеры под ГЕО, RTP-чувствительность, crash/instant для LatAm/India</td></tr>\n<tr><td><b>7. CRM/Retention</b></td><td>переводы, лайфсайкл, каналы (мессенджеры в emerging)</td></tr>\n<tr><td><b>8. Launch &amp; iterate</b></td><td>трафик (аффилиаты, стримеры, комьюнити), замер по когортам</td></tr>\n</table></div>"}, {"title": "Локальные платёжные методы", "summary": "Главный технический рычаг FTD-конверсии. Карты часто не работают: ~40% игроков после неуспешного депозита не пробуют снова.", "terms": ["Бразилия", "Pix", "ЛатАм (прочее)", "Индия", "UPI", "Африка", "M-Pesa", "Европа", "Pay-N-Play", "ЮВ Азия", "СНГ / high-risk", "Крипто", "Правило для кассы", "approval rate в конкретном ГЕО"], "body": "<p class=\"lead\">Главный технический рычаг FTD-конверсии. Карты часто не работают: ~40% игроков после неуспешного депозита не пробуют снова.</p><div class=\"tbl-wrap\"><table>\n<tr><th style=\"width:26%;\">Регион</th><th>Ключевые методы</th></tr>\n<tr><td><b>Бразилия</b></td><td><b>Pix</b> (~96% рынка беттинга, мгновенный A2A); кредитки под запретом, закрытый bank-to-bank loop</td></tr>\n<tr><td><b>ЛатАм (прочее)</b></td><td>Мексика — OXXO-ваучеры + SPEI; Колумбия — PSE; Mercado Pago; Pix-подобные растут</td></tr>\n<tr><td><b>Индия</b></td><td><b>UPI</b> (млрд транзакций), Paytm, netbanking; частые заморозки каналов → smart routing</td></tr>\n<tr><td><b>Африка</b></td><td><b>M-Pesa</b> (Кения/Танзания, 90%+), MTN MoMo / Airtel Money (Зап. Африка), USSD</td></tr>\n<tr><td><b>Европа</b></td><td>open banking / A2A, <b>Pay-N-Play</b> (Trustly), iDEAL (NL), BLIK (PL), SEPA Instant</td></tr>\n<tr><td><b>ЮВ Азия</b></td><td>PromptPay (TH), MoMo (VN), QRIS (ID), GCash (PH) — mobile-first</td></tr>\n<tr><td><b>СНГ / high-risk</b></td><td>карты, СБП, P2P с автоподбором реквизита, крипта/стейблкоины</td></tr>\n<tr><td><b>Крипто</b></td><td>дополнение, особенно в emerging (Индия, Нигерия, Вьетнам, Бразилия); баланс фиат/крипто</td></tr>\n</table></div><div class=\"note\"><b>Правило для кассы:</b> смотреть не на % комиссии, а на <b>approval rate в конкретном ГЕО</b>. 6% при 85% аппрува лучше, чем 3% при 60%. Плюс — payment orchestration и cascading (каскад методов при отказе).</div>"}, {"title": "Адаптация продукта", "summary": "Технически Mobile monopoly: в Tier-3 95%+ трафика с мобилок, часто старых → лёгкие лендинги, быстрый первый экран. APK/webview/PWA под сторовые ограничения; low-data режимы. Device fingerprint на кассе (риск identity theft в LatAm). Продуктово Бонусы под покуп", "terms": ["Mobile monopoly", "Бонусы под покупательную способность", "Поддержка и трафик"], "body": "<div class=\"grid2\">\n<div><div class=\"block-title\">Технически</div>\n<ul class=\"tips\">\n<li><b>Mobile monopoly:</b> в Tier-3 95%+ трафика с мобилок, часто старых → лёгкие лендинги, быстрый первый экран.</li>\n<li>APK/webview/PWA под сторовые ограничения; low-data режимы.</li>\n<li>Device fingerprint на кассе (риск identity theft в LatAm).</li>\n</ul></div>\n<div><div class=\"block-title\">Продуктово</div>\n<ul class=\"tips\">\n<li><b>Бонусы под покупательную способность:</b> низкий средний деп в emerging; выше bonus abuse (Бразилия/Африка) → anti-abuse + лимиты.</li>\n<li>Слоты и провайдеры — свои топы под ГЕО; RTP-чувствительность.</li>\n<li><b>Поддержка и трафик</b> через мессенджеры (Telegram/WhatsApp), стримеры, аффилиаты.</li>\n</ul></div>\n</div>"}, {"title": "Самопроверка", "summary": "Вопросов: 3 Развернуть всё ", "terms": [], "body": "<div data-qa-group=\"\">\n</div>"}], "source": "Source A"}, {"id": "tiers", "title": "Тиры GEO", "icon": "▲", "stages": [{"title": "Три тира", "summary": "Tier 4 (редко) — закрытые/нестабильные экономики (Афганистан, Иран и т.п.), обычно вне интереса: почти нет трафика/паблишеров и жёсткие ограничения.", "terms": ["Tier 4"], "body": "<div class=\"card\">\n<div class=\"card-head\"><div class=\"stage-badge\" style=\"background:#4f46e5;\">1</div>\n<div><h3 class=\"card-title\">Tier 1 — премиум, зрелые рынки</h3>\n<div class=\"lead\" style=\"margin:0;\">Высокий ARPU/LTV, дорогой трафик, строгая регуляторика, доверие к бренду важнее бонуса.</div></div></div>\n<div class=\"grid2\">\n<div><div class=\"block-title\">Страны</div><p style=\"font-size:13px;\">США, UK, Ирландия, Канада, Австралия, Нов. Зеландия, Германия, Франция, Скандинавия (Швеция, Норвегия, Финляндия, Дания), Нидерланды, Швейцария, Австрия.</p></div>\n<div><div class=\"block-title\">Характер</div><ul class=\"tips\">\n<li>Высокий CAC, высокий LTV, R2D может быть 30–40%+.</li>\n<li>Ждут secure-платежи, лицензию, премиум-брендинг.</li>\n<li>Жёсткая реклама (GDPR/UKGC/ASA/FTC).</li>\n</ul></div>\n</div>\n</div><div class=\"card\">\n<div class=\"card-head\"><div class=\"stage-badge\" style=\"background:#0d9488;\">2</div>\n<div><h3 class=\"card-title\">Tier 2 — растущие, средний доход</h3>\n<div class=\"lead\" style=\"margin:0;\">Оптимум цена/качество, дешевле трафик, локализация — ключ к конверсии.</div></div></div>\n<div class=\"grid2\">\n<div><div class=\"block-title\">Страны</div><p style=\"font-size:13px;\">Бразилия, Мексика, Аргентина, Чили, Польша, Румыния, Испания, Португалия, Италия, Греция, Турция, Украина, Ю. Корея, Япония (грей), Индонезия, Таиланд, Малайзия, ЮАР.</p></div>\n<div><div class=\"block-title\">Характер</div><ul class=\"tips\">\n<li>Средний CAC/LTV, ниже конкуренция, растущий интерес.</li>\n<li>Развивающаяся регуляторика и платёжная инфраструктура.</li>\n<li>Критична локализация (язык, валюта, локальные платёжки — Pix и т.п.).</li>\n</ul></div>\n</div>\n</div><div class=\"card\">\n<div class=\"card-head\"><div class=\"stage-badge\" style=\"background:#f59e0b;\">3</div>\n<div><h3 class=\"card-title\">Tier 3 — emerging, объём и рост</h3>\n<div class=\"lead\" style=\"margin:0;\">Дешёвый трафик и огромные объёмы, но низкий LTV, высокий bonus-abuse, слабая платёжная инфра.</div></div></div>\n<div class=\"grid2\">\n<div><div class=\"block-title\">Страны</div><p style=\"font-size:13px;\">Индия, Нигерия, Кения, Гана, Танзания, Вьетнам, Бангладеш, Пакистан, Филиппины, Индонезия (частично), Перу, Колумбия и др.</p></div>\n<div><div class=\"block-title\">Характер</div><ul class=\"tips\">\n<li>Низкий CAC и низкий LTV, ставка на объём.</li>\n<li>Bonus-sensitive, low-stakes; mobile-monopoly (95%+, старые телефоны, 3G).</li>\n<li>Платёжки: mobile money, prepaid, крипта (нет традиц. банкинга).</li>\n</ul></div>\n</div>\n</div><div class=\"note blue\"><b>Tier 4</b> (редко) — закрытые/нестабильные экономики (Афганистан, Иран и т.п.), обычно вне интереса: почти нет трафика/паблишеров и жёсткие ограничения.</div>"}, {"title": "Как тир влияет на продукт", "summary": "Аспект Tier 1 Tier 3 Бонусы премиум/VIP, доверие важнее anti-abuse, низкие лимиты, bonus-sensitive Платежи карты, open banking, Pay-N-Play mobile money, prepaid, крипта Продукт богатый UX, десктоп+моб лёгкий мобайл, APK, low-data Экономика высокий CAC/LTV низк", "terms": [], "body": "<div class=\"tbl-wrap\"><table>\n<tr><th style=\"width:22%;\">Аспект</th><th style=\"width:39%;\">Tier 1</th><th style=\"width:39%;\">Tier 3</th></tr>\n<tr><td>Бонусы</td><td>премиум/VIP, доверие важнее</td><td>anti-abuse, низкие лимиты, bonus-sensitive</td></tr>\n<tr><td>Платежи</td><td>карты, open banking, Pay-N-Play</td><td>mobile money, prepaid, крипта</td></tr>\n<tr><td>Продукт</td><td>богатый UX, десктоп+моб</td><td>лёгкий мобайл, APK, low-data</td></tr>\n<tr><td>Экономика</td><td>высокий CAC/LTV</td><td>низкий CAC/LTV, объём</td></tr>\n<tr><td>Реклама</td><td>строгая (GDPR/лицензии)</td><td>свободнее, popunder/native</td></tr>\n</table></div>"}, {"title": "Самопроверка", "summary": "Вопросов: 3 Развернуть всё ", "terms": [], "body": "<div data-qa-group=\"\">\n</div>"}], "source": "Source A"}, {"id": "market", "title": "Рынок & стратегия", "icon": "◉", "stages": [{"title": "Рынок 2025 в цифрах", "summary": "Монетизация-2025: высокая отдача в мультипродуктовых платформах с крипто-интеграциями и связке Crash / Instant Win / Live Casino — быстрый вход, понятная логика, масштабируемость. Но баланс фиат/крипто важнее ставки только на крипто.", "terms": ["Монетизация-2025", "Crash / Instant Win / Live Casino"], "body": "<div class=\"kpi-strip\">\n<div class=\"kpi\"><div class=\"k\">Рынок GGR 2025</div><div class=\"v\">$186 млрд</div><div class=\"d\">$285 млрд к 2029 · CAGR 11.6%</div></div>\n<div class=\"kpi\"><div class=\"k\">Доля online</div><div class=\"v\">30.5%</div><div class=\"d\">→ 37.4% к 2029</div></div>\n<div class=\"kpi\"><div class=\"k\">Mobile-first</div><div class=\"v\">~60%</div><div class=\"d\">выручки со смартфонов</div></div>\n<div class=\"kpi\"><div class=\"k\">ЛатАм mobile</div><div class=\"v\">+26%</div><div class=\"d\">за 5 лет · драйвер роста</div></div>\n</div><div class=\"tbl-wrap\"><table>\n<tr><th style=\"width:34%;\">Срез</th><th>Данные 2025</th></tr>\n<tr><td>Регионы GGR</td><td>Европа 41% · Азия/БВ 24% · Сев. Америка 21% · ЛатАм 5% · Океания 4.5% · Африка 3%</td></tr>\n<tr><td>Структура mobile GGR</td><td>ставки ~60% · казино ~30% · лотереи ~10%</td></tr>\n<tr><td>Прогноз 2029</td><td>Европа ↓ до 35% · США ↑ до 30% · ЛатАм и Африка — активный рост</td></tr>\n<tr><td>Драйверы</td><td>США, Ближний Восток, ЛатАм; гибкий продуктовый микс (ставки+казино+лотереи)</td></tr>\n</table></div><div class=\"note\"><b>Монетизация-2025:</b> высокая отдача в мультипродуктовых платформах с крипто-интеграциями и связке <b>Crash / Instant Win / Live Casino</b> — быстрый вход, понятная логика, масштабируемость. Но баланс фиат/крипто важнее ставки только на крипто.</div>"}, {"title": "Как конкурировать с топами", "summary": "Точечное усиление продукта: у крупных брендов много пробелов (устаревшие welcome-паки, негибкие бонусы) — их закрывают сильные спецы. Гибкость бонусов под тип трафика/связку. Комьюнити: чат на сайте, креативный SMM, локальные лидеры мнений, живые модераторы — ", "terms": ["Точечное усиление продукта", "Комьюнити", "Retention", "Кассир", "Итог"], "body": "<ul class=\"tips\">\n<li><b>Точечное усиление продукта:</b> у крупных брендов много пробелов (устаревшие welcome-паки, негибкие бонусы) — их закрывают сильные спецы. Гибкость бонусов под тип трафика/связку.</li>\n<li><b>Комьюнити:</b> чат на сайте, креативный SMM, локальные лидеры мнений, живые модераторы — бренд перестаёт быть «неодушевлённым».</li>\n<li><b>Retention:</b> кастомные беттинг-события, максимальная сегментация в ПЛ, свежие механики турниров/розыгрышей (у китов до этого часто не доходят руки).</li>\n<li><b>Кассир:</b> эксперименты с фаст-кнопками, лимитами, апсейлом, таймерами под сегменты — прирост до ~5% на объёмах окупается.</li>\n<li><b>Итог:</b> будущее за продуктовой гибкостью и персонализацией.</li>\n</ul>"}, {"title": "Зрелость продуктового мышления", "summary": "Зрелый подход Управляет когортами, бонусной нагрузкой, платёжной конверсией, NGR, удержанием — а не только докупает трафик и тушит пожары. Есть стратегия развития на метриках с проработанными KPI. Радость за выполнение плана на квартал/год, а не за отдельную з", "terms": [], "body": "<div class=\"grid2\">\n<div class=\"card\" style=\"flex:1 1 280px;\">\n<h3 class=\"card-title\">Зрелый подход</h3>\n<ul class=\"tips\">\n<li>Управляет <b>когортами, бонусной нагрузкой, платёжной конверсией, NGR, удержанием</b> — а не только докупает трафик и тушит пожары.</li>\n<li>Есть стратегия развития на метриках с проработанными KPI.</li>\n<li>Радость за выполнение плана на квартал/год, а не за отдельную задачу.</li>\n</ul>\n</div>\n<div class=\"card\" style=\"flex:1 1 280px;\">\n<h3 class=\"card-title\">Незрелый / симптомный</h3>\n<ul class=\"tips\">\n<li>Фокус на фичах «что сделать», а не «зачем и какую метрику меняем».</li>\n<li>Постоянно лечит симптомы (рассылки на 100500 сегментов) и называет это стратегией.</li>\n<li>Разрыв между командами: маркетинг льёт одно, CRM работает массово, платежи не под ГЕО, аналитика опаздывает.</li>\n</ul>\n</div>\n</div>"}, {"title": "Типовые ошибки брендов", "summary": "VIP-ориентир (для контекста). Средний депозит топ-брендов: Duel в пике ~$4 368 (после урезания ПЛ упал до ~$939), Gamdom ~$1 485. Показывает, насколько сильно ПЛ и позиционирование двигают средний чек хайроллеров.", "terms": ["Сегментация/локализация рассылок", "Курсы валют", "Антифрод", "Игровой менеджмент", "Ошибки на сайте", "VIP-ориентир (для контекста)"], "body": "<ul class=\"tips\">\n<li><b>Сегментация/локализация рассылок:</b> иностранный текст не той аудитории.</li>\n<li><b>Курсы валют:</b> при фиат+крипто или мультивалюте — либо абуз ушлыми игроками, либо вал жалоб.</li>\n<li><b>Антифрод:</b> экономика бонусов «на глаз», ручные триггеры, слабые условия блокировок → потеря лояльности/лицензии.</li>\n<li><b>Игровой менеджмент:</b> мусор в топе, низкий RTP на чувствительном ГЕО, старые визуалы, минусовые/нищие промо.</li>\n<li><b>Ошибки на сайте:</b> голое «error» без смысла — каждая ошибка должна направлять игрока.</li>\n</ul><div class=\"note blue\"><b>VIP-ориентир (для контекста).</b> Средний депозит топ-брендов: Duel в пике ~$4 368 (после урезания ПЛ упал до ~$939), Gamdom ~$1 485. Показывает, насколько сильно ПЛ и позиционирование двигают средний чек хайроллеров.</div>"}, {"title": "Самопроверка", "summary": "Вопросов: 3 Развернуть всё ", "terms": [], "body": "<div data-qa-group=\"\">\n</div>"}], "source": "Source A"}, {"id": "role", "title": "Карта вакансии", "icon": "◫", "stages": [{"title": "Product ownership", "summary": "Не «вести задачи», а обнаруживать проблему, определять impact, выбирать решение и измерять эффект.", "terms": [], "body": "<div class=\"card\"><h3>Product ownership</h3><p>Не «вести задачи», а обнаруживать проблему, определять impact, выбирать решение и измерять эффект.</p></div>"}, {"title": "Analytics", "summary": "Funnel, conversion, cohorts, retention, segmentation, event analytics, диагностика падений.", "terms": [], "body": "<div class=\"card\"><h3>Analytics</h3><p>Funnel, conversion, cohorts, retention, segmentation, event analytics, диагностика падений.</p></div>"}, {"title": "Experimentation", "summary": "Hypothesis → A/B design → sample → launch → interpretation → decision.", "terms": [], "body": "<div class=\"card\"><h3>Experimentation</h3><p>Hypothesis → A/B design → sample → launch → interpretation → decision.</p></div>"}, {"title": "Delivery", "summary": "Backlog, priority, acceptance criteria, dependencies, risk, deadlines.", "terms": [], "body": "<div class=\"card\"><h3>Delivery</h3><p>Backlog, priority, acceptance criteria, dependencies, risk, deadlines.</p></div>"}, {"title": "Cross-functional", "summary": "Analytics, dev, QA, retention/CRM, high-value/VIP, B2B.", "terms": [], "body": "<div class=\"card\"><h3>Cross-functional</h3><p>Analytics, dev, QA, retention/CRM, high-value/VIP, B2B.</p></div>"}, {"title": "GEO / Market", "summary": "Локальный контекст, конкурентный анализ, платежи, язык, регуляторика, привычки пользователей.", "terms": [], "body": "<div class=\"card\"><h3>GEO / Market</h3><p>Локальный контекст, конкурентный анализ, платежи, язык, регуляторика, привычки пользователей.</p></div>"}], "source": "Source B"}, {"id": "analytics", "title": "Analytics + SQL", "icon": "⌕", "stages": [{"title": "Amplitude / Mixpanel", "summary": "", "terms": [], "body": "<div class=\"card\"><h3>Amplitude / Mixpanel</h3><ul><li>Events + properties</li><li>Funnels: где drop-off</li><li>Segmentation: где именно</li><li>Cohorts/retention: кто возвращается</li><li>Paths: что было до/после события</li></ul></div>"}, {"title": "SQL", "summary": "", "terms": [], "body": "<div class=\"card\"><h3>SQL</h3><ul><li>SELECT / WHERE</li><li>GROUP BY + aggregates</li><li>JOIN</li><li>CASE WHEN</li><li>CTE</li><li>Window functions</li></ul></div>"}], "source": "Source B"}, {"id": "head", "title": "Правая рука Head", "icon": "✓", "stages": [{"title": "Analytics", "summary": "Decision question, metric definition, baseline, population, segments, decision rule.", "terms": [], "body": "<div class=\"card\"><h3>Analytics</h3><p>Decision question, metric definition, baseline, population, segments, decision rule.</p></div>"}, {"title": "Retention", "summary": "Требовать cohort + segment view, не удовлетворяться средней цифрой.", "terms": [], "body": "<div class=\"card\"><h3>Retention</h3><p>Требовать cohort + segment view, не удовлетворяться средней цифрой.</p></div>"}, {"title": "VIP / high-value", "summary": "Отдельно следить за качеством критичных сценариев и trend сегмента.", "terms": [], "body": "<div class=\"card\"><h3>VIP / high-value</h3><p>Отдельно следить за качеством критичных сценариев и trend сегмента.</p></div>"}, {"title": "B2B", "summary": "Feature request клиента — input; roadmap определяется повторяемостью проблемы и impact.", "terms": [], "body": "<div class=\"card\"><h3>B2B</h3><p>Feature request клиента — input; roadmap определяется повторяемостью проблемы и impact.</p></div>"}, {"title": "Cross-team", "summary": "Приносить owner гипотезу и evidence, а не «диагноз».", "terms": [], "body": "<div class=\"card\"><h3>Cross-team</h3><p>Приносить owner гипотезу и evidence, а не «диагноз».</p></div>"}, {"title": "Head support", "summary": "Priorities, dependencies, risks, owners, deadlines, decision log.", "terms": [], "body": "<div class=\"card\"><h3>Head support</h3><p>Priorities, dependencies, risks, owners, deadlines, decision log.</p></div>"}], "source": "Source B"}, {"id": "cases", "title": "Кейсы → принципы", "icon": "◆", "stages": [{"title": "FTD/first conversion trap", "summary": "Первая конверсия без downstream cohort может быть vanity metric.", "terms": [], "body": "<div class=\"card\"><h3>FTD/first conversion trap</h3><p>Первая конверсия без downstream cohort может быть vanity metric.</p></div>"}, {"title": "Retention average trap", "summary": "Общий D7 может скрыть деградацию конкретной группы.", "terms": [], "body": "<div class=\"card\"><h3>Retention average trap</h3><p>Общий D7 может скрыть деградацию конкретной группы.</p></div>"}, {"title": "Foreign GEO", "summary": "Похожий симптом ≠ одинаковая причина. Проверяй local context.", "terms": [], "body": "<div class=\"card\"><h3>Foreign GEO</h3><p>Похожий симптом ≠ одинаковая причина. Проверяй local context.</p></div>"}, {"title": "Scaling", "summary": "Test small → fix → scale stepwise → re-check quality.", "terms": [], "body": "<div class=\"card\"><h3>Scaling</h3><p>Test small → fix → scale stepwise → re-check quality.</p></div>"}, {"title": "CustDev sample bias", "summary": "Кого рекрутировал, то и услышал. Не интервьюировать только лояльных.", "terms": [], "body": "<div class=\"card\"><h3>CustDev sample bias</h3><p>Кого рекрутировал, то и услышал. Не интервьюировать только лояльных.</p></div>"}, {"title": "Ownership", "summary": "Помогай соседнему owner, не перехватывая ответственность.", "terms": [], "body": "<div class=\"card\"><h3>Ownership</h3><p>Помогай соседнему owner, не перехватывая ответственность.</p></div>"}], "source": "Source B"}, {"id": "segmentation", "title": "Сегментация игроков", "icon": "◎", "stages": [{"title": "Незарегистрированные: очень короткая сессия", "summary": "Источник связывает этот сегмент прежде всего с фундаментальными барьерами на входе.", "terms": [], "body": "<div class=\"knowledge-card\"><h3>Незарегистрированные: очень короткая сессия</h3><p>Источник связывает этот сегмент прежде всего с фундаментальными барьерами на входе.</p><ul><li>скорость загрузки и технические ошибки;</li><li>перегруз интерфейса и лишние pop-up;</li><li>несоответствие рекламного обещания первому экрану;</li><li>различия по GEO/device/source.</li></ul><span class=\"metric-chip\">session duration</span><span class=\"metric-chip\">exit rate</span><span class=\"metric-chip\">load/error rate</span></div>"}, {"title": "Незарегистрированные: средняя сессия", "summary": "Пользователь проявил интерес, но не дошёл до следующего шага.", "terms": [], "body": "<div class=\"knowledge-card\"><h3>Незарегистрированные: средняя сессия</h3><p>Пользователь проявил интерес, но не дошёл до следующего шага.</p><ul><li>paths до выхода;</li><li>видимость и понятность CTA;</li><li>form start → complete;</li><li>content relevance и локализация.</li></ul></div>"}, {"title": "Незарегистрированные: длинная сессия", "summary": "Экспертный материал трактует их как пользователей, которые ищут нужную информацию, но не находят ясного пути.", "terms": [], "body": "<div class=\"knowledge-card\"><h3>Незарегистрированные: длинная сессия</h3><p>Экспертный материал трактует их как пользователей, которые ищут нужную информацию, но не находят ясного пути.</p><ul><li>navigation/path analysis;</li><li>информационная архитектура;</li><li>dead ends и циклы;</li><li>несовпадение ожиданий и реального контента.</li></ul></div>"}, {"title": "Зарегистрированные без следующего ключевого действия", "summary": "Acquisition и регистрация уже сработали; диагностика переносится дальше по воронке.", "terms": [], "body": "<div class=\"knowledge-card\"><h3>Зарегистрированные без следующего ключевого действия</h3><p>Acquisition и регистрация уже сработали; диагностика переносится дальше по воронке.</p><ul><li>локализация критичного сценария;</li><li>доступность локальных методов;</li><li>error_code и понятность ошибок;</li><li>frontend ↔ backend outcome;</li><li>качество и скорость support handoff.</li></ul></div>"}, {"title": "Маркетинг ↔ продукт", "summary": "Если креатив обещает одно, а landing показывает другое, возникает trust gap. Для PM это cross-functional problem, а не только проблема маркетинга.", "terms": [], "body": "<div class=\"knowledge-card\"><h3>Маркетинг ↔ продукт</h3><p>Если креатив обещает одно, а landing показывает другое, возникает trust gap. Для PM это cross-functional problem, а не только проблема маркетинга.</p></div>"}, {"title": "Локализация", "summary": "Не только перевод: валюта, документы, форматы полей, локальные методы, тексты ошибок, культурные ожидания и ограничения рынка.", "terms": [], "body": "<div class=\"knowledge-card\"><h3>Локализация</h3><p>Не только перевод: валюта, документы, форматы полей, локальные методы, тексты ошибок, культурные ожидания и ограничения рынка.</p></div>"}, {"title": "Support как часть продукта", "summary": "В критичных сценариях время и качество поддержки становятся частью UX и должны попадать в диагностику.", "terms": [], "body": "<div class=\"knowledge-card\"><h3>Support как часть продукта</h3><p>В критичных сценариях время и качество поддержки становятся частью UX и должны попадать в диагностику.</p></div>"}, {"title": "Payment reliability", "summary": "PM должен видеть success/fail/retry rate, причины ошибок, внешние зависимости и fallback-логику платформы.", "terms": [], "body": "<div class=\"knowledge-card\"><h3>Payment reliability</h3><p>PM должен видеть success/fail/retry rate, причины ошибок, внешние зависимости и fallback-логику платформы.</p></div>"}], "source": "Source B"}, {"id": "industry", "title": "B2B / платформа", "icon": "▣", "stages": [{"title": "B2B platform ≠ только frontend", "summary": "Платформа — это integrations, configuration, localization, reliability, monitoring, support и способность адаптироваться под рынок.", "terms": [], "body": "<div class=\"knowledge-card\"><h3>B2B platform ≠ только frontend</h3><p>Платформа — это integrations, configuration, localization, reliability, monitoring, support и способность адаптироваться под рынок.</p></div>"}, {"title": "White Label vs source-code model", "summary": "Разные бизнес-модели меняют roadmap, ownership, customization, SLA и support burden.", "terms": [], "body": "<div class=\"knowledge-card\"><h3>White Label vs source-code model</h3><p>Разные бизнес-модели меняют roadmap, ownership, customization, SLA и support burden.</p></div>"}, {"title": "Платежные интеграции", "summary": "Подключение, отключение и переключение провайдеров — постоянный технический и операционный риск, поэтому важны abstraction, monitoring и fallback.", "terms": [], "body": "<div class=\"knowledge-card\"><h3>Платежные интеграции</h3><p>Подключение, отключение и переключение провайдеров — постоянный технический и операционный риск, поэтому важны abstraction, monitoring и fallback.</p></div>"}, {"title": "GEO adaptation", "summary": "Техническая переносимость не означает готовность рынка: нужны локальные методы, UX conventions, regulation, marketing context и QA.", "terms": [], "body": "<div class=\"knowledge-card\"><h3>GEO adaptation</h3><p>Техническая переносимость не означает готовность рынка: нужны локальные методы, UX conventions, regulation, marketing context и QA.</p></div>"}, {"title": "Качество ТЗ", "summary": "Неясные требования создают переделки и рассинхрон. Для PM: problem statement, outcome, scope, edge cases, analytics, dependencies и acceptance criteria.", "terms": [], "body": "<div class=\"knowledge-card\"><h3>Качество ТЗ</h3><p>Неясные требования создают переделки и рассинхрон. Для PM: problem statement, outcome, scope, edge cases, analytics, dependencies и acceptance criteria.</p></div>"}, {"title": "AI / automation", "summary": "Источники позиционируют AI как вспомогательный слой для эффективности и персонализации, а не как замену product/operations expertise.", "terms": [], "body": "<div class=\"knowledge-card\"><h3>AI / automation</h3><p>Источники позиционируют AI как вспомогательный слой для эффективности и персонализации, а не как замену product/operations expertise.</p></div>"}, {"title": "Sportsbook B2B", "summary": "Важен не только софт, но и expertise партнёра, операционное сопровождение, risk-management capabilities и качество поддержки.", "terms": [], "body": "<div class=\"knowledge-card\"><h3>Sportsbook B2B</h3><p>Важен не только софт, но и expertise партнёра, операционное сопровождение, risk-management capabilities и качество поддержки.</p></div>"}, {"title": "VIP / high-value service", "summary": "Для PM-фокуса важны безопасность данных, SLA, надежность коммуникации, сервис и снижение operational friction.", "terms": [], "body": "<div class=\"knowledge-card\"><h3>VIP / high-value service</h3><p>Для PM-фокуса важны безопасность данных, SLA, надежность коммуникации, сервис и снижение operational friction.</p></div>"}], "source": "Source B"}], "questions": [{"q": "Чем отличается GGR от NGR и почему продакту важнее NGR?", "a": "GGR = оборот − выигрыши игроков. NGR = GGR − бонусы − налоги − платёжные/платформенные комиссии (− chargeback). NGR — реальная база прибыли и расчёта RevShare с аффилиатами. Продакт влияет на него через контроль bonus cost, качество трафика и retention, поэтому именно NGR — правильный «финальный» KPI улучшений воронки.", "cat": "iGaming — общая система"}, {"q": "R2D падает при стабильных регистрациях — где искать причину?", "a": "Утечка сидит между регистрацией и кассой: добавленный шаг KYC, убранный/сломанный способ оплаты, мутные бонус-условия, платёжные фейлы, либо просадка качества трафика (наплыв бонус-хантеров). Диагностика: разложить переход рег→FTD по этапам, сегментам, источникам и платёжным методам, найти конкретный шаг с обвалом.", "cat": "iGaming — общая система"}, {"q": "Как поднять retention D30, не раздувая bonus cost?", "a": "Геймификация и миссии в реальном времени, лайфсайкл-CRM по свежим данным, ранние сигналы оттока с триггерными офферами, отдельный VIP-трек для ядра. Оптимизировать на retained NGR , а не на выданных бонусах; использовать D7 как ранний индикатор, чтобы не ждать 30 дней.", "cat": "iGaming — общая система"}, {"q": "Как сбалансировать анти-фрод и конверсию?", "a": "Через трейд-офф detection rate vs false-positive rate и risk-adaptive пороги: высокая чувствительность на высокорисковых событиях (вывод, крупный бонус), мягкая — на рутине, чтобы беречь UX. Измерять долю ложных срабатываний и её влияние на конверсию, а не только пойманный фрод.", "cat": "iGaming — общая система"}, {"q": "Какие метрики положишь на дашборд воронки?", "a": "По 1–2 на этап: CR визит→рег, R2D, FTD→2-й депозит, retention D7/D30, ARPU/ARPPU, LTV/CAC — плюс guardrail'ы (chargeback rate, bonus/GGR, deposit success rate). Принцип из теории метрик: 1–2 показателя из каждой категории для health-check, а не всё подряд.", "cat": "iGaming — общая система"}, {"q": "Что делает метрику «хорошей»?", "a": "Она: число; понятна команде; привязана к цели; имеет прозрачную формулу; связана с другими; побуждает к действию; имеет источник и период. Финальный тест: «если значение изменится — что сделаем иначе?» Если ответа нет — метрика лишняя.", "cat": "Продуктовые метрики"}, {"q": "Назови классификацию продуктовых метрик.", "a": "9 категорий: Acquisition, Activation, Engagement, Retention, Revenue, Happiness, Technical, Operational, Specific . Здоровый дашборд — по 1–2 метрики из каждой для контроля состояния продукта.", "cat": "Продуктовые метрики"}, {"q": "Что такое North Star Metric и как её строить?", "a": "Агрегированная метрика ценности, ведущая к росту дохода (подход Amplitude). Пример e-com: Ширина (MAU покупателей) × Интенсивность (средний чек) × Частота покупок . Обязательно добавить guardrails (возвраты, качество доставки), чтобы рост не шёл за счёт качества.", "cat": "Продуктовые метрики"}, {"q": "Что такое aha-момент и как его измерять?", "a": "Ключевое действие, где юзер впервые получает значимую ценность (первая покупка, добавление друзей). Измеряется через долю дошедших до него и time-to-aha — время достижения.", "cat": "Продуктовые метрики"}, {"q": "Меняются ли метрики по стадиям продукта?", "a": "Да. PSF — качественная обратная связь; PMF — retention/engagement/acquisition/монетизация; Growth — acquisition/monetization/activation/retention + операционные; Maturity — операционная эффективность и технические метрики.", "cat": "Продуктовые метрики"}, {"q": "Как выбрать источник данных, если их несколько?", "a": "Взять наиболее достоверный (например, бэкенд-базу для транзакций), остальные использовать для сверки. Расхождение между источниками не должно превышать 10% . И договориться в команде о единых формулах и определениях.", "cat": "Продуктовые метрики"}, {"q": "Чем A/B тест лучше сравнения «до-после»?", "a": "A/B изолирует причинный эффект изменения от внешнего фона — сезонности, смены качества трафика, маркетинга, цен, макро-событий. «До-после» смешивает эффект фичи с этими факторами, поэтому рост метрики после релиза сам по себе ничего не доказывает.", "cat": "A/B testing"}, {"q": "Что такое MDE и как он влияет на выборку?", "a": "MDE — минимальный детектируемый эффект, который эксперимент должен уметь заметить. Чем меньше MDE, тем больше нужна выборка и дольше тест. Нереалистично маленький MDE — частая причина «недомощных» тестов.", "cat": "A/B testing"}, {"q": "В чём разница статистической и бизнес-значимости?", "a": "Статистическая значимость: эффект вряд ли случаен (низкий p-value). Бизнес-значимость: эффект достаточно большой, чтобы окупить внедрение. Результат может быть значимым, но бесполезным — тогда его сравнивают с cost of change.", "cat": "A/B testing"}, {"q": "Что такое SRM и почему это красный флаг?", "a": "Sample Ratio Mismatch — расхождение планового и фактического сплита (план 50/50, факт 60/40). Группы могут стать несопоставимы, и разница в метриках окажется следствием технического сбоя, а не продукта. Проверять до интерпретации результата.", "cat": "A/B testing"}, {"q": "Почему нельзя «подглядывать» за результатами?", "a": "Многократные промежуточные проверки повышают вероятность ложноположительного вывода (накопление ошибки первого рода). Тест нужно завершать по заранее заданному правилу (размер выборки / срок), а не останавливать в момент «красивой» разницы.", "cat": "A/B testing"}, {"q": "Зачем нужны guardrail-метрики?", "a": "Это защитные метрики (ошибки, скорость загрузки, возвраты, жалобы): показывают, не ухудшилось ли что-то критичное, пока растёт primary. Решение нельзя принимать только по primary — если просели guardrail'ы, надо разобрать побочный ущерб.", "cat": "A/B testing"}, {"q": "Что такое оборачиваемость депозита и почему она важна?", "a": "Bets Sum (real) / Deposits Sum , целевое 8–10. Показывает, сколько раз игрок «прокручивает» депозит в ставках. Пример: депозит $1000, RTP 96% (маржа 4%). При обороте 7× GGR = $280, при 10× = $400 с того же депозита. Растёт через доверие, программу лояльности (мотивация на объём спинов) и игровой менеджмент (слоты с высоким КПД).", "cat": "iGaming метрики"}, {"q": "Что такое КПД слота и как его использовать?", "a": "Bets Count / Active Unique Users — среднее число ставок на игрока в слоте. Два слота с одинаковым оборотом, но разным КПД дают разный GGR на аккаунт: чем больше спинов на игрока, тем выше оборачиваемость и доход. КПД помогает приоритизировать лобби и выбирать слоты/провайдеров под своё ГЕО.", "cat": "iGaming метрики"}, {"q": "Что показывает InOut % и какой бенчмарк?", "a": "Процент выводов от суммы депозитов, ориентир 25–35% в зависимости от стратегии. Резкий рост — сигнал bonus-abuse, слишком «щедрой» отдачи или проблем с продуктом. Смежная метрика Cash Ratio (кэш/GGR) следит за ликвидностью.", "cat": "iGaming метрики"}, {"q": "Какие метрики сигналят, что слот «умирает»?", "a": "PAU падает 7+ дней подряд, CTR из лобби снижается, Session Length сокращается, Unique Bets на игрока и средняя ставка падают, слабый Slot Retention. CTR и Session Length проседают раньше PAU — это ранние маркеры. Реакция: понизить слот, дать микро-буст (ивент/промо), сверить с соседними слотами, проверить тех-стабильность.", "cat": "iGaming метрики"}, {"q": "Как бы ты выстроил reload-бонус?", "a": "Через прозрачную систему уровней: 10+ уровней от суммы ставок за месяц, удержание уровня — 50% от его KPI, ежемесячный бонус без вагера растёт с уровнем. Плюс нематериальные перки (кастомизация, ранний доступ к пререлизам и high-RTP слотам). Это удерживает и повышает оборачиваемость без раздувания bonus cap.", "cat": "Бонусы & игры"}, {"q": "Какой тип бонусного баланса выбрать и почему?", "a": "Заблокированный («нафталин») даёт лучшую маржу, но ловит жалобы, роняет конверсию в 4-й деп и растит churn (~+20%). Распространённый (отыгрыш сперва с реала) — рабочий компромисс с конвертом около бенча. Гибридный 50/50 честнее и поднимает конверсию, но легче абузится и режет маржу. Практичный дефолт — «распространённый», гибрид — при сильном риск-менеджменте.", "cat": "Бонусы & игры"}, {"q": "Как посчитать нагрузку welcome-бонуса на GGR?", "a": "Welcome Pack Costs = AVG FTD × % бонуса (например $50 × 10% = $5 на игрока). Всегда считать ДО релиза, по шансам/лимитам/сегментам, и сопоставлять с AVG GGR per FTD. Вагер ×1 — прозрачный ориентир; контроль вагера — через блэклисты игр (коэф отыгрыша, волатильность, категории).", "cat": "Бонусы & игры"}, {"q": "Когда начинать делать брендовые игры?", "a": "Ориентир — GGR > $10M/мес. Бренд-слот делать с топ-10 провайдером проекта, RTP 97–98%, с реальной кастомизацией (загрузочный экран, маскот, бонуска). Краш/инстант — лучше инхаус-командой. Слот без хорошего КПД/LTV = деньги на ветер и удар по репутации.", "cat": "Бонусы & игры"}, {"q": "Как настроить турнир, чтобы он работал?", "a": "Длительность 2–3 дня (дольше игроки не любят ждать приз), бюджет ~0.05–0.3% месячного GGR, KPI по сумме ставок или сумме мультипликаторов, лидерборд 20–30 позиций, главный приз ≥20% фонда как «морковка» для крупных сегментов. Свой турнир — все слоты; с провайдером — топ по перформансу/удержанию.", "cat": "Retention & CJM"}, {"q": "Как быстро поднять конверсию Click2Reg?", "a": "Форма реги в один экран на мобилке без попапов поверх, можно прямо на главной; позиционирование конкретными цифрами («up to $4000», не «400%»); промокод в форме с автоподстановкой по UTM; пролив сразу на форму или авто-открытие. Чем меньше шагов — тем лучше; отдельный шаг выбора бонуса обычно конвертит хуже.", "cat": "Retention & CJM"}, {"q": "Когда логичнее всего поддерживать игрока бонусом?", "a": "В момент затяжного слива: игроки чаще уходят после серии проигрышей и быстрого слива баланса, а не после выигрыша. Ловить это по Velocity of Spend и триггерить поддержку/коммуникацию именно тогда. В остальное время инструменты вовлечения для него — фон.", "cat": "Retention & CJM"}, {"q": "Какие проблемы у когорты 2–4-го депозита?", "a": "Не сформирована привычка, welcome-эффект «выветрился», а reload-механик либо нет, либо они слабые. Лечится нормальной системой уровней/reload, ситуативными retention-бонусами по триггерам и работой с ранними сигналами оттока — до того, как игрок ушёл.", "cat": "Retention & CJM"}, {"q": "Что такое CRM в iGaming и зачем он продукту?", "a": "Система управления жизненным циклом и коммуникациями игрока: сегментация + триггерные кампании + мультиканал (email/push/SMS/on-site/мессенджеры). Задача — поднять LTV и снизить отток, доводя новорега до FTD/2-го депозита, удерживая привычку и возвращая спящих. Судить эффективность по incremental NGR (uplift к контролю), а не по числу рассылок.", "cat": "CRM"}, {"q": "Почему real-time в CRM важнее «ночного батча»?", "a": "Главное окно конверсии — первая сессия. Батч-CRM обновляет данные ночью и не может среагировать, пока игрок в приложении. Real-time триггер на депозит/поведение в моменте работает в разы лучше. Отсюда тренд на единый data-слой (CDP + исполнение) и real-time движки.", "cat": "CRM"}, {"q": "Какие CRM-сценарии выстроишь первыми?", "a": "Welcome journey (рег→FTD), FTD→2-й депозит, churn-prevention по ранним сигналам, win-back по паузе и VIP-nurture. Плюс downswing-support по Velocity of Spend. Каждый сценарий — с primary-метрикой и контрольной группой для замера uplift, а не массовая рассылка «всем».", "cat": "CRM"}, {"q": "Что такое KYC и зачем он нужен?", "a": "Проверка личности, возраста и источника средств игрока: документ + liveness, 18+, proof of address, source of funds для крупных сумм, PEP/sanctions screening. Нужен для лицензии/регуляторики, борьбы с фродом и мультиаккаунтами, ответственной игры и защиты от chargeback/AML. Это часть compliance, а не просто «загрузите паспорт».", "cat": "KYC & Compliance"}, {"q": "Как не убить конверсию тяжёлым KYC?", "a": "Risk-based / progressive KYC: лёгкая проверка на входе (показать ценность раньше), усиленную верификацию (EDD, документы, source of funds) сдвинуть к выводу/лимиту или к high-risk/high-value кейсам. Автоверификация (OCR+liveness+базы) с fallback на ручную. Мерить KYC pass rate (>80–90%), time-to-verify и drop-off на KYC.", "cat": "KYC & Compliance"}, {"q": "Как KYC связан с anti-fraud и responsible gaming?", "a": "KYC — фундамент: подтверждённая личность отсекает мультиаккаунты и bonus-abuse (в связке с device fingerprint, Deposit Source Mismatch), питает AML (source of funds, мониторинг транзакций) и responsible gaming (возраст 18+, self-exclusion, лимиты). Pay-N-Play даже совмещает KYC с депозитом, убирая форму регистрации.", "cat": "KYC & Compliance"}, {"q": "С чего начнёшь вывод продукта на новый ГЕО?", "a": "Research (рынок, конкуренты по чек-листу, sentiment в мессенджерах) → регуляторика (regulated/grey/black, лицензия, налоги, реклама) → локальные платёжки → локализация носителями → адаптация продукта под мобайл/инфраструктуру → контент под ГЕО → CRM/retention → запуск и итерации по когортам. Платёжки и регуляторика — самые «дорогие» ошибки.", "cat": "Новый GEO"}, {"q": "Какие платёжки нужны для Бразилии, Индии, Африки?", "a": "Бразилия — Pix (≈96% рынка, кредитки под запретом, закрытый bank-to-bank loop). Индия — UPI + Paytm (с оговоркой на заморозки каналов и smart routing). Африка — M-Pesa (Кения/Танзания), MTN MoMo/Airtel Money (Зап. Африка), USSD. Смотреть на approval rate в ГЕО, а не только на комиссию, и делать cascading при отказах.", "cat": "Новый GEO"}, {"q": "Как адаптировать продукт под emerging-рынок?", "a": "Mobile-first и легковесность (95%+ трафика с мобилок, часто старых, слабый интернет): лёгкие лендинги, APK/PWA, low-data. Локальные платёжки и валюта, бонусы под низкую покупательную способность с усиленным anti-abuse (bonus-хантеры выше в Бразилии/Африке), слоты/провайдеры под ГЕО, поддержка и трафик через Telegram/WhatsApp и стримеров. ARPU ниже, но объём и рост выше.", "cat": "Новый GEO"}, {"q": "Что такое тиры ГЕО и зачем они?", "a": "Условная классификация рынков по покупательной способности, стоимости трафика, конкуренции и регуляторике. Tier 1 — богатые зрелые рынки (высокий ARPU/LTV, дорогой трафик, строгая регуляторика), Tier 2 — растущие средние, Tier 3 — emerging (объём и дешёвый трафик, низкий LTV). Нужны для приоритизации трафика, планирования CAC и бонусной/платёжной стратегии. Классификация не единая — комбинируется с regulated/grey/black.", "cat": "Тиры GEO"}, {"q": "Приведи примеры стран по тирам.", "a": "Tier 1: США, UK, Канада, Австралия, Германия, Скандинавия, Нидерланды. Tier 2: Бразилия, Мексика, Аргентина, Польша, Испания, Португалия, Италия, Турция, Ю. Корея, ЮАР. Tier 3: Индия, Нигерия, Кения, Вьетнам, Бангладеш, Пакистан, Филиппины, Перу. Границы условны — конкретная страна может быть в разных тирах у разных сетей.", "cat": "Тиры GEO"}, {"q": "Чем продуктовая стратегия для Tier 1 отличается от Tier 3?", "a": "Tier 1 — премиум-брендинг, доверие и лицензия важнее бонуса, карты/open banking/Pay-N-Play, богатый UX, высокий CAC/LTV, строгая реклама. Tier 3 — легковесный мобайл (APK/low-data), локальные платёжки (mobile money/крипта), anti-abuse и низкие лимиты (bonus-sensitive аудитория), ставка на объём при низком LTV. Локализация и платёжки решают конверсию сильнее, чем в Tier 1.", "cat": "Тиры GEO"}, {"q": "Куда движется рынок iGaming и что это значит для продукта?", "a": "Рынок ~$186 млрд GGR в 2025 (CAGR ~11.6%), online-доля растёт к 37% к 2029, mobile-first — базовый минимум (~60% выручки с мобайла). Драйверы роста — США, Ближний Восток, ЛатАм, Африка. Для продукта: приоритет мобильной скорости/UX, гибкий микс (ставки+казино+лотереи), локализация под растущие ГЕО и связка Crash/Instant/Live.", "cat": "Рынок & стратегия"}, {"q": "Как небольшому бренду конкурировать с топами?", "a": "Не в лоб по трафику, а через продуктовую гибкость: точечно закрывать пробелы гигантов (устаревшие welcome-паки, негибкие бонусы под связки), строить комьюнити (чат, SMM, локальные лидеры), инвестировать в retention и сегментацию ПЛ, экспериментировать в кассире. На дистанции выигрывает тот, кто накапливает игроков и персонализирует.", "cat": "Рынок & стратегия"}, {"q": "Чем зрелый продуктовый подход отличается от «тушения пожаров»?", "a": "Зрелый управляет когортами, бонусной нагрузкой, платёжной конверсией, NGR и удержанием по стратегии с KPI. Незрелый докупает трафик, тушит операционные пожары и лечит симптомы (массовые рассылки), называя это стратегией. Признак разрыва — маркетинг/CRM/платежи/аналитика не синхронизированы, и продукт теряет деньги ежедневно.", "cat": "Рынок & стратегия"}, {"q": "Продакт пришёл в новый iGaming-продукт — с чего начнёшь по метрикам?", "a": "Описать текущие метрики (формула, источник, владелец), классифицировать по категориям, выделить health-check для текущей стадии, определить/уточнить North Star и guardrails. Затем разложить воронку по этапам, найти самую большую утечку и приоритизировать по влиянию на NGR.", "cat": "Смешанные"}, {"q": "Как выбрать North Star для беттинг-приложения?", "a": "По логике ценности «Ширина × Интенсивность × Частота»: например, число активных игроков × средний размер ставки/депозита × частота ставок за период. Guardrails: bonus/GGR, chargeback rate, доля ответственной игры. NSM должна вести к росту NGR, а не к «пустому» обороту.", "cat": "Смешанные"}, {"q": "CAC вырос, LTV не изменился — что делаешь?", "a": "Проверяю, не упало ли качество трафика (R2D, retention по источникам), режу неокупаемые каналы, работаю над эффективным CAC (креативы, message match, реактивация вместо покупки нового). Параллельно поднимаю LTV через retention/монетизацию, чтобы удержать LTV/CAC ≥3–4×. MAC держу ≤25–30% LTV сегмента.", "cat": "Смешанные"}, {"q": "Тебе дали 40 метрик — как не утонуть?", "a": "Классифицировать по 9 категориям, выделить ключевые health-check под текущую стадию продукта, для остальных определить владельцев. Собрать дашборд из 1–2 метрик на категорию. Для каждой прогнать тест «изменится — что сделаем иначе?» и убрать те, что не ведут к действию.", "cat": "Смешанные"}, {"q": "Как измеришь активацию в казино?", "a": "Через aha-момент — например, первый депозит + первая игровая сессия с «маленькой победой». Метрики: доля дошедших до aha и time-to-aha (время рег→первая значимая ценность). Короткий time-to-aha коррелирует с лучшим retention.", "cat": "Смешанные"}, {"q": "Разные источники дают разные цифры по депозитам — как быть?", "a": "Выбрать самый достоверный источник как источник истины (обычно бэкенд-база транзакций), остальные — для сверки. Расхождение >10% — сигнал проблемы с трекингом/определениями. Договориться в команде о единой формуле и периоде.", "cat": "Смешанные"}, {"q": "Хочешь протестировать новый экран депозита. Спроектируй тест.", "a": "Гипотеза: упрощение кассы (депозит в один тап) повысит R2D для новых игроков за счёт снижения фрикшна. Primary — R2D; secondary — deposit success rate, time-to-FTD; guardrail — chargeback rate, ошибки платежей. Единица рандомизации — игрок. Выборку/срок считаю из MDE и базовой конверсии, фиксирую критерий до старта, проверяю SRM, завершаю по правилу.", "cat": "Смешанные"}, {"q": "Тест показал +2% к конверсии, p<0.05. Катим?", "a": "Не автоматически. Проверяю: нет ли SRM, не просели ли guardrail'ы (chargeback, возвраты), достаточно ли эффект велик относительно cost of change, и укладывается ли ДИ в бизнес-значимый диапазон. Значимо ≠ полезно. Если всё чисто — катим с пост-релиз мониторингом.", "cat": "Смешанные"}, {"q": "Когда A/B тест не нужен?", "a": "Когда трафика мало и тест шёл бы неоправданно долго; когда это багфикс/обязательная тех-корректировка; когда эффект заведомо мал и не окупает эксперимент; когда гипотеза уже опровергнута базовыми данными. Тест — инвестиция трафика и времени: запускаем, когда цена неопределённости выше стоимости эксперимента.", "cat": "Смешанные"}, {"q": "Retention D7 хороший, D30 проваливается — гипотезы?", "a": "Проблема глубины/лайв-опса, а не онбординга: контент заканчивается, нет прогрессии/миссий на средний срок, welcome-эффект выветрился без reload-механик. Проверяю по сегментам и вертикалям, тестирую миссии/лояльность и триггеры на ранние сигналы оттока. (D7→D30 обычно ~2:1.)", "cat": "Смешанные"}, {"q": "Как аргументируешь приоритет улучшения воронки vs закупки трафика?", "a": "Относительный рост конверсии воронки на 20% часто даёт больше NGR, чем рост трафика на 20% — без доп. CAC, потому что умножает ценность уже оплаченного трафика. Показываю на каскаде: где утечка и сколько FTD/NGR вернёт её починка против стоимости дополнительного трафика.", "cat": "Смешанные"}, {"q": "Как понять, что метрика «тщеславная» (vanity)?", "a": "Не проходит тест действия: её изменение ни к чему нас не обязывает. Классический пример в iGaming — число регистраций без привязки к FTD: растёт, а денег нет. Лечится связыванием с деньгами (R2D, NGR) и назначением ответственного.", "cat": "Смешанные"}, {"q": "GGR стабильный, но подозреваешь, что слот «умирает». Как проверишь?", "a": "Смотрю ранние маркеры до PAU: падение CTR из лобби и сокращение Session Length, затем снижение Unique Bets на игрока и средней ставки, слабый Slot Retention. Если трафик в лобби нормальный, а Unique Bets падает — проблема в самом слоте. Реакция: понизить в лобби, дать микро-буст (ивент/промо), сверить с соседними слотами, проверить тех-стабильность.", "cat": "Смешанные"}, {"q": "Тебе дают поднять оборачиваемость депозита. Твои рычаги?", "a": "Оборачиваемость = Bets real / Deposits (цель 8–10). Рычаги: доверие к проекту, программа лояльности, мотивирующая на объём спинов, и игровой менеджмент — вывод в топ слотов с высоким КПД (Bets Count / Active Users) под моё ГЕО. Рост с 7× до 10× при марже ~4% поднимает GGR с депозита на ~40%.", "cat": "Смешанные"}, {"q": "Как контролировать нагрузку бонусов на экономику?", "a": "Держать Bonus Cap в 15–30% от GGR, считать стоимость каждого бонуса ДО релиза (Welcome Costs = AVG FTD × %), трекать Max Bonus Exposure по дням, Bonus Abuse Cluster на рисковых ГЕО и InOut% (25–35%). Вагер контролировать блэклистами игр, а не просто повышать цифру вагера.", "cat": "Смешанные"}, {"q": "Реши: вознаграждать всех игроков или только активных?", "a": "Сильная гипотеза — смещать поддержку в момент затяжного слива, а не только награждать за активность. Игроки чаще уходят после серии проигрышей и быстрого слива баланса (ловим по Velocity of Spend), реже — после выигрыша. Раннее внимание к перспективным и «остывающим» даёт больше депозитов и конверсий, чем ковровые рассылки.", "cat": "Смешанные"}, {"q": "Какие продуктовые коммуникации выберешь под апсейл на депозит?", "a": "Попап на критичном этапе CJM/по триггеру (не спамить на кассе и главной новорега) + быстрый депозит мобильной плашкой с любой страницы (сумма + метод, автоподбор реквизита для СНГ). Позиционирование конкретной цифрой оффера, модалки на все виды неуспешной оплаты с кросс-селлом. Не заваливать турнирами — это режет конверт.", "cat": "Смешанные"}, {"q": "С чего начнёшь оптимизацию Reg2FTD в кассире?", "a": "Разложу воронку кассира: заход в кассир → выбор метода → успешная оплата (Failed Deposit Rate, Deposit→Real Play). Быстрые рычаги: фаст-кнопки сумм, быстрый депозит плашкой с любой страницы, автоподбор реквизита, локальные методы под ГЕО, осмысленные ошибки с кросс-селлом. Прирост даже ~5% на объёмах окупается; проверяю гипотезы A/B-тестом с решением по retained NGR.", "cat": "Смешанные"}, {"q": "Тебе поручили запуск в новом ГЕО (Бразилия/Индия). Приоритеты?", "a": "Регуляторика (лицензия, налоги, реклама) и локальные платёжки первыми: Бразилия — Pix (кредитки под запретом, закрытый bank-to-bank loop), Индия — UPI/Paytm с учётом заморозок каналов. Дальше — локализация носителями, лёгкий мобайл (APK/low-data, 95%+ трафика с мобилок), бонусы под покупательную способность с anti-abuse, слоты под ГЕО, CRM с локальными каналами (Telegram/WhatsApp). Approval rate платёжек важнее комиссии.", "cat": "Смешанные"}, {"q": "Как KYC влияет на конверсию и что с этим делать?", "a": "Тяжёлый KYC на входе съедает 30–50% будущих депозиторов. Решение — risk-based / progressive KYC: лёгкая проверка на входе, усиленная (EDD, source of funds) к выводу/лимиту или для high-value/high-risk. Автоверификация OCR+liveness, мерить KYC pass rate (>80–90%), time-to-verify и drop-off. Pay-N-Play вообще совмещает KYC с депозитом, убирая форму.", "cat": "Смешанные"}, {"q": "Как разложить iGaming-воронку от входящего трафика до первого ключевого результата?", "a": "Разбиваю путь на отдельные переходы: visit → registration → verification/setup → first successful key action → repeat use → retention. Для каждого считаю conversion/drop-off и сегментирую по GEO, source, device и cohort. Практический кейс Telegram показывает: если трафик и регистрации есть, а следующий ключевой результат проваливается, причина может быть внутри продукта — локализация, платежный сценарий, технические ошибки, несоответствие GEO.", "cat": "Funnel"}, {"q": "Почему одна FTD/первая конверсия может вводить в заблуждение?", "a": "Первая конверсия не показывает качество пользователя. Я дополняю её источником, когортой, повторным действием и downstream retention. В Telegram-кейсе высокая первая конверсия выглядела хорошо, но 30-дневная когорта показала большой объём разовых пользователей. Это пример vanity metric без downstream quality.", "cat": "Metrics"}, {"q": "Что не так со средним D1/D7/D30 retention?", "a": "Среднее может скрывать противоположные тренды. Retention нужно смотреть когортно и по сегментам: new/active/high-value/reactivated, source, GEO, acquisition cohort. В Telegram-кейсе стабильный общий D7 маскировал ухудшение одной важной группы, слабое качество одного источника и эффект реактиваций.", "cat": "Retention"}, {"q": "Почему нельзя переносить гипотезу с одного GEO на другое без проверки?", "a": "Одинаковый симптом может иметь разные причины из-за платежной инфраструктуры, языка, регуляторики, устройств и локальных ожиданий. Я приношу гипотезу, а не диагноз. Telegram-разбор называет это локальной слепотой: без локального контекста даже знакомый паттерн легко интерпретировать неверно.", "cat": "GEO"}, {"q": "Ты увидел проблему в продукте соседней команды. Что делать?", "a": "Обращусь к owner и принесу observation + гипотезу + способ проверки. Не буду самовольно чинить и не пойду через голову без системной причины. Источник подчёркивает: сильный PM понимает границы своего контекста и помогает владельцу направления решить проблему, не забирая ownership.", "cat": "Leadership"}, {"q": "Когда продукт готов к масштабированию?", "a": "Когда стабильность подтверждена данными: ключевая воронка работает, когорты не ухудшаются при росте объёма, а ограничения и экономика понятны. Масштабирую ступенями. Telegram-кейс описывает методологию: сначала малый контролируемый объём, диагностика и исправления, затем постепенное увеличение с проверкой качества.", "cat": "Scale"}, {"q": "Как не испортить customer development неправильной выборкой?", "a": "Начинаю с research question и нужного сегмента. Если интервьюировать только лояльных, получу эхо-камеру. Нужны также ушедшие и проблемные пользователи. В Telegram-материале recruitment bias обозначен как ключевая ловушка: кого позвал, то и услышал.", "cat": "Research"}, {"q": "Почему красивый dashboard не равен хорошей аналитике?", "a": "Dashboard показывает, что произошло. PM должен понимать почему и что делать: definition метрики, baseline, сегменты, owner, alert threshold и next action. Практический материал критикует сотни метрик без decision logic. Мониторинг не заменяет диагностику.", "cat": "Analytics"}, {"q": "Что на самом деле измеряет A/B-тест?", "a": "Это контролируемый эксперимент со случайным распределением аудитории. Он оценивает причинный эффект изменения и помогает отделить его от случайного колебания. PDF подчёркивает: A/B-тест не гарантирует рост бизнеса и не заменяет стратегию; он снижает неопределённость.", "cat": "A/B"}, {"q": "Почему before/after слабее A/B-теста?", "a": "Потому что одновременно могут измениться сезонность, traffic mix, маркетинг, цены и внешняя среда. До/после смешивает эффект фичи с фоном. Это один из центральных тезисов PDF: рост после релиза не доказывает причинность.", "cat": "A/B"}, {"q": "Когда A/B-тест не стоит запускать?", "a": "Когда гипотеза уже опровергнута базовыми данными, трафика мало, изменение обязательное/техническое, ожидаемый эффект слишком мал или результат теста не изменит решение. В PDF дано правило: эксперимент оправдан, когда цена неопределённости выше стоимости эксперимента.", "cat": "A/B"}, {"q": "Что такое MDE?", "a": "Minimum Detectable Effect — минимальный эффект, который тест должен уметь обнаружить. Чем меньше MDE, тем обычно больше нужна выборка. MDE связывает бизнес-значимый порог с sample size и длительностью теста.", "cat": "A/B"}, {"q": "Что такое p-value простыми словами?", "a": "Это мера того, насколько необычен наблюдаемый результат при условии, что реального эффекта нет. Он не говорит, насколько эффект важен для бизнеса. PDF отдельно разделяет statistical significance и business significance.", "cat": "A/B"}, {"q": "Что такое мощность теста?", "a": "Power, 1−β — вероятность обнаружить реальный эффект, если он существует. Низкая мощность повышает риск false negative. Продакту не нужно выводить формулы, но нужно понимать связь power, MDE, baseline и sample size.", "cat": "A/B"}, {"q": "Зачем confidence interval, если есть p-value?", "a": "CI показывает диапазон правдоподобных значений истинного эффекта и неопределённость оценки. Широкий CI означает низкую точность. Незначимый результат с широким CI не равен доказательству отсутствия эффекта — тест может быть недомощным.", "cat": "A/B"}, {"q": "Что фиксируем до запуска A/B-теста?", "a": "Hypothesis, audience, primary metric, secondary/guardrail metrics, randomization unit, MDE, sample size, duration, success criteria и stop rule. По PDF хороший эксперимент начинается с дизайна, а не с разработки.", "cat": "A/B"}, {"q": "Primary vs secondary vs guardrail metrics?", "a": "Primary — метрика решения; secondary объясняет механизм; guardrail защищает от критического побочного ухудшения. Основную метрику нельзя выбирать после просмотра результата — это post-hoc подгонка.", "cat": "A/B"}, {"q": "Почему нельзя постоянно подглядывать и остановить тест при первом p<0.05?", "a": "Многократные проверки увеличивают риск false positive. Fixed-horizon тест завершают по заранее заданному правилу, кроме оговорённых технических/критических аномалий. Peeking в PDF указан как типичная ошибка.", "cat": "A/B"}, {"q": "Что такое SRM?", "a": "Sample Ratio Mismatch — заметное расхождение между ожидаемым и фактическим распределением по вариантам. До расследования результат не считаю доказательным. PDF приводит пример ожидаемых 50/50 и фактических 60/40 как технический red flag.", "cat": "A/B"}, {"q": "Почему post-hoc поиск выигрышного сегмента опасен?", "a": "Перебор сегментов после результата повышает вероятность случайной находки. Такой вывод exploratory, а не подтверждённый causal effect. PDF рекомендует ключевые сегменты задавать заранее или перепроверять post-hoc находку новым тестом.", "cat": "A/B"}, {"q": "Как выбрать единицу рандомизации?", "a": "Она должна соответствовать уровню применения изменения и метрики: user/account/device/session. Важно исключить попадание одной сущности в разные варианты. PDF предупреждает о неправильной единице анализа и несогласованности randomization/metric grain.", "cat": "A/B"}, {"q": "Что делать, если статистически значимо, но бизнес-эффект слишком мал?", "a": "Не внедрять автоматически. Сравнить effect size с cost of change, рисками, support cost и opportunity cost. Statistical significance ≠ business significance — прямой тезис PDF.", "cat": "A/B"}, {"q": "Что делать при незначимом результате и широком CI?", "a": "Не говорить «эффекта нет». Проверю мощность, sample size, MDE и data quality — тест может быть недомощным. Это отдельный сценарий решения в PDF.", "cat": "A/B"}, {"q": "Primary выросла, guardrail ухудшился — что делать?", "a": "Не принимать решение только по primary. Оценить размер побочного ущерба и его причину; возможно, reject или redesign. PDF требует учитывать защитные метрики как часть критерия решения.", "cat": "A/B"}, {"q": "Чем ABCD-тест отличается от A/B?", "a": "Сравнивает несколько вариантов одновременно. Требует больше трафика и осторожности из-за множественных сравнений. PDF подчёркивает trade-off: больше альтернатив, но выше статистические требования.", "cat": "A/B"}, {"q": "Метрика просела на 15%. Что делаешь первые 30 минут?", "a": "Проверяю tracking → момент начала → funnel step → сегменты → releases/incidents → hypotheses → validation. Не начинаю с редизайна. Это соединяет требования вакансии с Telegram-принципом «dashboard = что; PM = почему и что делать».", "cat": "Analytics"}, {"q": "Как использовать Amplitude/Mixpanel на интервью?", "a": "Events/properties → funnel → breakdown → cohorts/retention → paths. Инструмент использую для локализации проблемы и проверки гипотез, а не как просто dashboard. Middle PM должен объяснять аналитическую задачу каждого инструмента.", "cat": "Analytics"}, {"q": "Какой SQL нужен Middle PM?", "a": "SELECT, WHERE, GROUP BY, aggregates, JOIN, CASE WHEN, CTE и базовые window functions. Достаточно для самостоятельного sanity-check и простых продуктовых вопросов. PM не заменяет аналитика, но должен понимать grain, joins и definitions.", "cat": "SQL"}, {"q": "Все stakeholders говорят, что их задача срочная. Как приоритизировать?", "a": "Отделяю critical/mandatory, затем сравниваю impact, evidence/confidence, reach, effort, dependencies и strategic fit. Показываю trade-offs. Для правой руки Head важна прозрачная приоритизация нескольких направлений.", "cat": "Backlog"}, {"q": "Что значит быть правой рукой Head?", "a": "Собирать общую картину, переводить стратегию в initiatives/backlog, находить зависимости, поднимать риски и обеспечивать решения на данных. В структуре analytics + retention + VIP/high-value + B2B нужен influence without authority.", "cat": "Leadership"}, {"q": "Чем B2B PM отличается от B2C?", "a": "В B2B buyer, customer и end user могут быть разными ролями. Feature request — input, а не автоматический roadmap item. Нужно балансировать повторяемость проблемы, стратегический impact, интеграции, support cost и архитектуру.", "cat": "B2B"}, {"q": "Как ставить задачу разработке?", "a": "Problem statement → outcome/metric → scope/non-scope → flow → acceptance criteria → edge cases/errors → analytics → dependencies → DoD. Показывает способность PM связывать бизнес, аналитику, QA и разработку.", "cat": "Delivery"}], "glossary": [{"term": "Acquisition", "def": "Этап привлечения: откуда и какая аудитория приходит в продукт. Анализируют source mix, GEO, device, new/returning и downstream-поведение."}, {"term": "Session", "def": "Период взаимодействия пользователя с продуктом. Точное правило начала/окончания зависит от аналитической системы."}, {"term": "Source mix", "def": "Распределение трафика между источниками. Изменение mix способно изменить общую conversion даже без изменения поведения внутри каждого источника."}, {"term": "Attribution", "def": "Правило, по которому визит или конверсия связываются с источником/кампанией."}, {"term": "UTM", "def": "Параметры URL для маркировки source, medium, campaign и других атрибутов трафика."}, {"term": "Landing", "def": "Посадочная страница или первый экран, на который попадает пользователь из источника."}, {"term": "CTA", "def": "Call to Action — заметный и понятный призыв к следующему целевому действию."}, {"term": "Responsive", "def": "Корректная адаптация интерфейса к разным размерам экранов и устройствам."}, {"term": "Performance", "def": "Скорость и отзывчивость продукта: загрузка, рендеринг, latency и стабильность."}, {"term": "Exit rate", "def": "Доля выходов со страницы или экрана. Интерпретируется вместе с целью страницы и следующей conversion."}, {"term": "Breakdown", "def": "Разрез общей метрики по категориям: GEO, device, browser, version, source. Помогает локализовать проблему."}, {"term": "Cohort", "def": "Группа пользователей с общим стартовым событием/временем или признаком, поведение которой сравнивают во времени."}, {"term": "Segmentation", "def": "Разделение аудитории на группы по свойствам или поведению для более точного анализа."}, {"term": "Downstream", "def": "Последующие шаги после текущей точки воронки."}, {"term": "Uplift", "def": "Изменение метрики относительно baseline/control. Важно уточнять абсолютные п.п. или относительный рост."}, {"term": "Guardrail", "def": "Защитная метрика: показывает, не ухудшилось ли что-то критичное при росте primary metric."}, {"term": "FTD", "def": "First Time Deposit — первый успешный депозит пользователя."}, {"term": "R2D / Reg2Dep", "def": "Конверсия зарегистрированных пользователей в первый успешный депозит."}, {"term": "Completion rate", "def": "Доля пользователей, завершивших выбранный процесс или шаг."}, {"term": "Fail rate", "def": "Доля неуспешных попыток выбранного процесса."}, {"term": "Retry", "def": "Повторная попытка после ошибки, ожидания или неопределённого состояния."}, {"term": "Processing time", "def": "Время обработки операции или процесса."}, {"term": "SLA", "def": "Service Level Agreement — согласованный уровень качества/времени сервиса или внешней зависимости."}, {"term": "Frontend event", "def": "Событие, зафиксированное в пользовательском интерфейсе."}, {"term": "Backend outcome", "def": "Фактический результат операции на серверной стороне."}, {"term": "Recovery flow", "def": "Путь восстановления после ошибки: понятный статус и безопасный следующий шаг."}, {"term": "Activation", "def": "Первое получение ключевой ценности продукта. Activation event выбирают по связи с последующим успешным использованием."}, {"term": "Time-to-value", "def": "Время от старта пути до первого получения ключевой ценности."}, {"term": "Core action", "def": "Основное действие, отражающее ядро пользовательской ценности продукта."}, {"term": "Latency", "def": "Время между действием пользователя и реакцией системы."}, {"term": "Repeat rate", "def": "Доля пользователей, повторивших выбранное meaningful action."}, {"term": "Retention", "def": "Возврат к meaningful event спустя заданное время."}, {"term": "Exact-day retention", "def": "Возврат ровно в заданный день, например именно D7."}, {"term": "Rolling retention", "def": "Возврат в заданный день или позже, в зависимости от definition."}, {"term": "Churn", "def": "Прекращение активности по принятому в продукте определению."}, {"term": "GGR", "def": "Gross Gaming Revenue: валовой игровой результат по принятой в компании формуле, обычно оборот минус выплаты."}, {"term": "Hold", "def": "GGR как доля от turnover: относительный показатель валового результата."}, {"term": "NGR", "def": "Net Gaming Revenue — GGR после согласованных прямых корректировок; точный состав вычетов зависит от финансовой методологии компании."}, {"term": "ARPU", "def": "Средний доход на активного пользователя за период; numerator и definition active user должны быть зафиксированы."}, {"term": "ARPPU", "def": "Средний доход на платящего пользователя за период."}, {"term": "LTV", "def": "Ценность пользователя за жизненный цикл."}, {"term": "CAC", "def": "Стоимость привлечения пользователя/клиента по принятому определению acquisition cost."}, {"term": "DAU / WAU / MAU", "def": "Уникальные активные пользователи за день / неделю / месяц."}, {"term": "Stickiness", "def": "Показатель частоты возврата, часто DAU/MAU; смысл зависит от естественной частоты использования продукта."}, {"term": "Event", "def": "Зафиксированное действие или факт в event-based аналитике."}, {"term": "Event property", "def": "Контекст события: provider, device, source, error_code и т.д."}, {"term": "User property", "def": "Относительно устойчивый атрибут пользователя: GEO, platform, status и т.п."}, {"term": "Funnel", "def": "Заданная последовательность событий для анализа conversion и drop-off."}, {"term": "Path / Flow", "def": "Фактическая последовательность событий до или после выбранной точки."}, {"term": "MDE", "def": "Minimum Detectable Effect — минимальный эффект, который эксперимент должен уметь обнаружить."}, {"term": "Alpha", "def": "Заранее выбранный допустимый риск ложноположительного вывода."}, {"term": "p-value", "def": "Мера необычности результата при предположении отсутствия реального эффекта; не показывает бизнес-ценность."}, {"term": "Power", "def": "Вероятность обнаружить реальный эффект, если он существует."}, {"term": "Confidence interval", "def": "Диапазон правдоподобных значений эффекта; показывает неопределённость."}, {"term": "SRM", "def": "Sample Ratio Mismatch — несоответствие ожидаемого и фактического распределения участников по вариантам эксперимента."}, {"term": "Randomization unit", "def": "Уровень, на котором сущность назначается в A/B-вариант: user/account/device/session."}, {"term": "KYC", "def": "Know Your Customer — процедуры подтверждения личности/возраста и других обязательных данных согласно правилам рынка."}, {"term": "AML", "def": "Anti-Money Laundering — меры по противодействию отмыванию средств и мониторингу подозрительных операций."}, {"term": "Responsible Gaming", "def": "Механизмы безопасного и соответствующего регулированию использования продукта: лимиты, self-exclusion, cooling-off и др."}, {"term": "B2B", "def": "Модель, где покупатель/клиент и конечный пользователь могут быть разными ролями; важны API, configuration, SLA, integrations и support."}, {"term": "Acceptance criteria", "def": "Проверяемые условия, при которых задача считается реализованной корректно."}, {"term": "Definition of Done", "def": "Согласованный набор условий полной готовности задачи или инкремента."}, {"term": "Conversion", "def": "Доля пользователей, прошедших заданный переход."}, {"term": "Drop-off", "def": "Пользователи, не прошедшие следующий шаг."}, {"term": "Vanity metric", "def": "Цифра, которая выглядит хорошо, но слабо поддерживает решение."}]};